        --fab-size: 60px;
        --fab-menu-radius: 100px;
        position: absolute;
        bottom: 80px;
        right: 20px;
        width: var(--fab-size);
        height: var(--fab-size);
        z-index: 1001;
        transition: all 0.3s ease-in-out;
    }
    #fab-ball {
        width: 100%;
        height: 100%;
        background-color: var(--primary-color);
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        color: #1a1a1a;
        font-size: calc(var(--fab-size) / 2.5);
