        margin-left: calc(var(--fab-size) * -0.4);
        background: var(--hover-color);
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        color: #1a1a1a;
        font-size: calc(var(--fab-size) / 3);
        cursor: pointer;
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.5);
        transition: all 0.3s ease;
    }
