        function getValidPointPool(level) {
            const lvl = parseInt(level) || 1;
            if (lvl <= 10) return { min: 50, max: 80 };
            if (lvl <= 20) return { min: 81, max: 95 };
            if (lvl <= 30) return { min: 96, max: 115 };
            if (lvl <= 40) return { min: 116, max: 135 };
            if (lvl <= 50) return { min: 136, max: 155 };
            return { min: 156, max: 180 }; 
        }

        function calculateCustomTraitCost(bonusObject) {
            const totalBonus = Object.values(bonusObject || {}).reduce((sum, val) => sum + (parseInt(val) || 0), 0);
            const costMap = {
                '-5': -25, '-4': -20, '-3': -15, '-2': -10, '-1': -5,
                '0': 0, '1': 20, '2': 30, '3': 40, '4': 60, '5': 70
            };
            return costMap[totalBonus] || 0;
        }

        function calculateLevelFromPoints(points) {
            for (let level = 1; level <= 50; level++) {
                const pool = getValidPointPool(level);
                if (points <= pool.max) {
                    return level;
                }
            }
            return 50;
        }

        function getLevelFromAttributePoints(totalPoints) {
            for (let level = 1; level <= 100; level++) {
                const pool = getValidPointPool(level);
                if (totalPoints <= pool.max) {
                    return level;
                }
            }
            return 100;
        }

        function clampAttributeValue(attributeName, value) {
            const parsedValue = parseInt(value) || 0;
            const isSpecialAttr = attributeName === '信仰' || attributeName === '深渊亲和';
            const minValue = isSpecialAttr ? 0 : 1;
            const maxValue = 30;
            return Math.max(minValue, Math.min(parsedValue, maxValue));
        }

        function getPointCost(value, direction = 'increase', isCreation = false) {
            if (isCreation) {
                const targetValue = direction === 'increase' ? value : value - 1;
                if (targetValue < 12) return 1;
                if (targetValue < 15) return 2;
                if (targetValue < 18) return 3;
                return 4;
            } else {
                const targetValue = direction === 'increase' ? value : value + 1;
                if (targetValue <= 15) return 1;
                if (targetValue <= 20) return 2;
                if (targetValue <= 25) return 3;
                return 4;
            }
        }

        function getTableIndexFromId(id) {
            if (!id) return null;
            const prefix = id.substring(0, 2);
            if (prefix === 'IT') {
                return '2';
            }

            const singlePrefix = id.charAt(0);
            switch(singlePrefix) {
                case 'B':
                case 'C':
                case 'G':
                    return '0';
                case 'M':
                    return '10';
                case 'I':
                    return '1';
                case 'F':
                    return '3';
                case 'T':
                    return '6';
                case 'S':
                    return '8';
                case 'E':
                    return '5';
                case 'P':
                    return '7';
                default:
                    return null;
            }
        }

        function recalculateAndCorrectNpcStats(row) {
            if (!row) return;

            const MAX_LEVEL = 60;
            const ATTRIBUTE_CAP = 30;

            const favorability = parseInt(row['15'] || '0');
            const clampedFavorability = Math.max(-100, Math.min(100, favorability));
            if (favorability !== clampedFavorability) {
                row['15'] = String(clampedFavorability);
            }

            let attributes = row['11'] ? JSON.parse(row['11']) : {};
            let wasCorrected = false;

            for (const attr in attributes) {
                const minValue = (attr === '信仰' || attr === '深渊亲和') ? 0 : 1;
                attributes[attr] = Math.max(minValue, attributes[attr] || minValue);
                if (attributes[attr] > ATTRIBUTE_CAP) {
                    attributes[attr] = ATTRIBUTE_CAP;
                    wasCorrected = true;
                }
            }

            let totalPoints = Object.values(attributes).reduce((sum, val) => sum + (parseInt(val) || 0), 0);

            let level = parseInt(row['9'] || '1');
            if (typeof row['9'] === 'string' && row['9'].includes(':')) {
                const remarks = parseRemarksString(row['9']);
                level = parseInt(remarks.level || '1');
            }

            if (level > MAX_LEVEL) {
                level = MAX_LEVEL;
                row['9'] = level;
                if(row['17'] !== undefined) {
                    const requiredXp = calculateXPForLevel(level);
                    row['17'] = Math.min(row['17'], requiredXp - 1);
                }
                wasCorrected = true;
            }

            const validPool = getValidPointPool(level);

            if (row['0'] !== 'B1' && totalPoints > validPool.max) {
                wasCorrected = true;
                let pointsToReduce = totalPoints - validPool.max;
                const sortedAttrs = Object.keys(attributes)
                    .sort((a, b) => attributes[b] - attributes[a]);

                while (pointsToReduce > 0 && sortedAttrs.length > 0) {
                    let changedInLoop = false;
                    for (const attr of sortedAttrs) {
                        const minValue = (attr === '信仰' || attr === '深渊亲和') ? 0 : 1;
                        if (attributes[attr] > minValue) {
                            attributes[attr]--;
                            pointsToReduce--;
                            changedInLoop = true;
                            if (pointsToReduce === 0) break;
                        }
                    }
                    if (!changedInLoop) break;
                }
            }

            if (wasCorrected) {
                row['11'] = JSON.stringify(attributes);
            }

            const conModifier = Math.floor(((attributes['体质'] || 8) - 10) / 2);
            const intModifier = Math.floor(((attributes['智力'] || 8) - 10) / 2);
            const wisModifier = Math.floor(((attributes['精神'] || 8) - 10) / 2);

            const maxHP = 10 + (level * (5 + conModifier));
            const maxMP = 10 + (level * Math.max(1, 3 + intModifier + wisModifier));

            const [currentHP, oldMaxHP] = (row['6'] || '0|0').split('|').map(Number);
            const [currentMP, oldMaxMP] = (row['7'] || '0|0').split('|').map(Number);

            const isNewNpc = oldMaxHP === 0 && oldMaxMP === 0;

            if (isNewNpc || wasCorrected) {
                row['6'] = `${maxHP}|${maxHP}`;
                row['7'] = `${maxMP}|${maxMP}`;
            } else {
                const hpIncrease = maxHP - oldMaxHP;
                const newCurrentHP = Math.max(0, Math.min(maxHP, currentHP + hpIncrease));
                const mpIncrease = maxMP - oldMaxMP;
                const newCurrentMP = Math.max(0, Math.min(maxMP, currentMP + mpIncrease));
                row['6'] = `${newCurrentHP}|${maxHP}`;
                row['7'] = `${newCurrentMP}|${maxMP}`;
            }

            if (isNewNpc && level >= 1 && row['17'] === undefined) {
                const requiredXp = calculateXPForLevel(level);
                const minXp = Math.floor(requiredXp * 0.2);
                const maxXp = Math.floor(requiredXp * 0.8);
                row['17'] = Math.floor(Math.random() * (maxXp - minXp + 1)) + minXp;
            }
        }

        async function applyChanges(baseState, delta) {
            let newState = JSON.parse(JSON.stringify(baseState));
            const changeLog = [];
            const newlyCreatedNpcIds = new Set();
            let currentTimeString = (newState['4']?.[0]?.['0'] || '').split('/')[0];

            const filteredDelta = delta.filter(op => {
                if (op.command === 'deleteRow' && op.id === 'B1') {
                    console.warn('已阻止删除玩家(B1)的非法操作。');
                    return false;
                }
                return true;
            });

            const oldPlayerLevel = baseState['0']?.['B1']?.['9'] || 1;

            for (const op of filteredDelta) {
                try {
                    const { command, id, data, eventData } = op;
                    if (command === 'updateRow' && id === "TIME_LOCATION_ROW") {
                        const timeRow = (newState['4'] || []).find(row => row.id === "TIME_LOCATION_ROW") || newState['4'][0];
                        if (timeRow) {
                            Object.assign(timeRow, data);
                            currentTimeString = (timeRow['0'] || '').split('/')[0];
                        }
                        continue;
                    }

                    const tableIndex = getTableIndexFromId(id || data?.['0']);
                    if (tableIndex === null && command !== 'addWorldEvent') continue;
                    if (!newState[tableIndex]) newState[tableIndex] = {};

                    switch (command) {
                        case 'insertRow':
                            newState[tableIndex][data['0']] = data;
                            if ((tableIndex === '0' || tableIndex === '10') && data['0'] !== 'B1') {
                                recalculateAndCorrectNpcStats(newState[tableIndex][data['0']]);
                            }
                            break;
                        case 'updateRow':
                            if (newState[tableIndex] && newState[tableIndex][id]) {
                                const oldRow = { ...(baseState[tableIndex]?.[id] || {}) };
                                const targetRow = newState[tableIndex][id];

                                for (const [key, value] of Object.entries(data)) {
                                    const oldValue = oldRow[key];
                                    if ((key === '6' || key === '7') && !String(value).includes('|')) {
                                        const [, maxVal] = (oldValue || `0|0`).split('|').map(Number);
                                        targetRow[key] = `${value}|${maxVal}`;
                                    } else if (key === '20') {
                                        const oldBooleans = parseRemarksString(oldValue);
                                        const newBooleans = parseRemarksString(value);
                                        targetRow[key] = serializeRemarksObject({ ...oldBooleans, ...newBooleans });
                                    }
                                    else {
                                        targetRow[key] = value;
                                    }
                                }

                                if (tableIndex === '0' && (id.startsWith('C') || id.startsWith('G'))) {
                                    const oldBooleans = parseRemarksString(oldRow['20']);
                                    const newBooleans = data['20'] ? parseRemarksString(data['20']) : oldBooleans;

                                    const wasPresent = oldBooleans.isPresent !== 'false';
                                    const isNowAbsent = newBooleans.isPresent === 'false';

                                    if (wasPresent && isNowAbsent) {
                                        targetRow['21'] = currentTimeString;
                                    } else if (!wasPresent && newBooleans.isPresent === 'true') {
                                        targetRow['21'] = '';
                                    }
                                }
                                if (tableIndex === '0' || tableIndex === '10') {
                                    recalculateAndCorrectNpcStats(targetRow);
                                }
                            }
                            break;
                        case 'deleteRow':
                            if (newState[tableIndex] && newState[tableIndex][id]) {
                                const idPrefix = id.charAt(0);
                                if (idPrefix === 'C' || idPrefix === 'G') {
                                    if (newState['1']) {
                                        Object.keys(newState['1']).forEach(itemId => {
                                            if (newState['1'][itemId]['8'] === id) {
                                                delete newState['1'][itemId];
                                            }
                                        });
                                    }
                                    if (newState['8']) {
                                        Object.keys(newState['8']).forEach(skillId => {
                                            if (newState['8'][skillId]['11'] === id) {
                                                delete newState['8'][skillId];
                                            }
                                        });
                                    }
                                }
                                delete newState[tableIndex][id];
                            }
                            break;
                        case 'addWorldEvent':
                            if (!newState['5']) newState['5'] = [];
                            newState['5'].push(eventData);
                            break;
                    }
                } catch (e) { console.error('应用更改时出错:', op, e); }
            }

            const newPlayerRow = newState['0']?.['B1'];
            if (newPlayerRow) {
                const newPlayerLevel = newPlayerRow['9'] || 1;
                if (newPlayerLevel > oldPlayerLevel) {
                    const pointsPerLevel = (level) => level > 30 ? 2 : 1;
                    let pointsGained = 0;
                    for(let i = oldPlayerLevel; i < newPlayerLevel; i++) {
                        pointsGained += pointsPerLevel(i + 1);
                    }

                    const currentPoints = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;
                    await dbSet(`ATTRIB_POINTS_${currentArchiveName}`, currentPoints + pointsGained);
                    showDanmaku(`等级提升! ${oldPlayerLevel} -> ${newPlayerLevel}。获得 ${pointsGained} 属性点！`, 'player');
                    const fabAttributeBtn = document.querySelector('.fab-item[data-action="attributes"]');
                    if (fabAttributeBtn && !fabAttributeBtn.querySelector('.red-dot')) {
                        const dot = document.createElement('span');
                        dot.className = 'red-dot red-dot-animation';
                        fabAttributeBtn.appendChild(dot);
                        setTimeout(() => dot.classList.remove('red-dot-animation'), 2000);
                    }
                }
            }

            const summonedPet = Object.values(newState['7'] || {}).find(p => {
                try { return parseRemarksString(p['20']).isSummoned === 'true'; } catch(e) { return false; }
            });
            if (summonedPet && delta.some(op => op.command === 'updateRow' && op.id === 'B1' && op.data['17'] !== undefined)) {
                const oldPlayerXp = baseState['0']?.['B1']?.['17'] || 0;
                const newPlayerXp = newState['0']['B1']['17'];
                const playerXpGain = newPlayerXp - oldPlayerXp;
                 if (playerXpGain > 0) {
                     const petXpGain = Math.floor(playerXpGain * 0.75);
                     let petLevel = parseInt(summonedPet['9'] || '1');
                     let petCurrentXp = (parseInt(summonedPet['17']) || 0) + petXpGain;
                     let petRequiredXp = calculatePetXPForLevel(petLevel);

                     while(petCurrentXp >= petRequiredXp) {
                         petCurrentXp -= petRequiredXp;
                         petLevel++;
                         petRequiredXp = calculatePetXPForLevel(petLevel);
                         showDanmaku(`${summonedPet['1'].split('|')[0]} 等级提升! -> Lv.${petLevel}`, 'achievement');
                     }
                     summonedPet['9'] = petLevel;
                     summonedPet['17'] = petCurrentXp;
                 }
            }
            return { state: newState, log: changeLog };
        }

        function extractCommands(text) {
            const commands = [];
            const commandRegex = /(updateRow|insertRow|deleteRow|addWorldEvent|addSmallSummary|addLargeSummary)\s*\(/g;
            let match;

            while ((match = commandRegex.exec(text)) !== null) {
                const commandName = match[1];
                const startIndex = match.index + commandName.length;
                let openParens = 0;
                let endIndex = -1;

                for (let i = startIndex; i < text.length; i++) {
                    if (text[i] === '(') {
                        openParens++;
                    } else if (text[i] === ')') {
                        openParens--;
                        if (openParens === 0) {
                            endIndex = i;
                            break;
                        }
                    }
                }

                if (endIndex !== -1) {
                    const fullCommand = text.substring(match.index, endIndex + 1);
                    commands.push(fullCommand);
                    commandRegex.lastIndex = endIndex;
                }
            }
            return commands;
        }

