        async function addAction(type, data, context = {}) {
            let actionText = '';
            switch(type) {
                case 'use':
                    const existingAction = actionQueue.find(a => a.type === 'use' && a.item.name === data.name);
                    if (existingAction) {
                        existingAction.quantity++;
                        renderActionQueue();
                        closeItemDetail();
                        return;
                    }
                    actionText = `使用 ${data.name}`;
                    break;
                case 'travel':
                    actionText = `前往 ${data.location}`;
                    break;
                case 'gift':
                    actionText = `将[${data.name}]赠送给${context.charName}`;
                    break;
                case 'submit_task':
                    const task = currentState['6'][data.id];
                    if (task && task['9'] === 'completed') {
                        showLoading('正在结算任务奖励...');
                        let rewardDelta = [];
                        if (task['12']) {
                            try {
                                const rewards = JSON.parse(task['12']);
                                if (Array.isArray(rewards)) {
                                    rewards.forEach(reward => {
                                        switch (reward.type) {
                                            case 'money':
                                                const playerRowMoney = currentState['0']['B1'];
                                                if(playerRowMoney) playerRowMoney['18'] = (playerRowMoney['18'] || 0) + reward.amount;
                                                break;
                                            case 'item':
                                                const newItemId = reward.id || `I_REWARD_${crypto.randomUUID()}`;
                                                rewardDelta.push({ command: 'insertRow', data: { '0': newItemId, '1': reward.name || '未知物品', '2': reward.itemType || '杂物', '3': reward.desc || '', '4': reward.effect || '', '5': (reward.quantity || 1).toString(), '7': (reward.value || 0).toString(), '8': 'B1' } });
                                                break;
                                            case 'favor':
                                                const targetChar = currentState['0'][reward.target];
                                                if(targetChar) targetChar['15'] = (parseInt(targetChar['15']) || 0) + reward.amount;
                                                break;
                                            case 'xp':
                                                const playerRowXp = currentState['0']['B1'];
                                                if(playerRowXp) playerRowXp['17'] = (playerRowXp['17'] || 0) + reward.amount;
                                                break;
                                        }
                                    });
                                }
                            } catch(e) { console.error("Error parsing task reward JSON:", e); }
                        }

                        if(rewardDelta.length > 0) {
                            const changes = await applyChanges(currentState, rewardDelta);
                            currentState = changes.state;
                        }

                        currentState['6'][data.id]['9'] = 'closed';
                        await saveCurrentState();
                        syncStateFromTables();
                        hideLoading();
                        showDanmaku(`委托 [${data.name}] 已提交！`, 'achievement');
                        tasksOverlay.classList.remove('visible');
                        await showCustomAlert('委托已提交，奖励已发放！');

                    } else {
                        await showCustomAlert('该任务尚未完成或不存在，无法提交。');
                    }
                    return;
            }

            if(type === 'travel') {
                 actionQueue = actionQueue.filter(a => a.type !== 'travel');
            }

            actionQueue.push({ type, text: actionText, data: data, context: context });

            renderActionQueue();

            if(type === 'use') closeItemDetail();
            if(type === 'travel') {
                locationDetailOverlay.classList.remove('visible');
                locationRpgOverlay.classList.remove('visible');
            }
        }

