        async function saveToLog(archiveName, newEntry) {
            try {
                const archive = await db.archives.get(archiveName);
                if (!archive) return;

                if (newEntry.stateSnapshot) {
                    try {
                        const snapshotObject = JSON.parse(newEntry.stateSnapshot);
                        if (snapshotObject.npcAvatars) {
                            await dbSet(`${NPC_AVATARS_KEY}_${archiveName}`, snapshotObject.npcAvatars);
                            delete snapshotObject.npcAvatars;
                            newEntry.stateSnapshot = JSON.stringify(snapshotObject);
                        }
                    } catch (e) {
                        console.error("Error processing stateSnapshot before saving log:", e);
                    }
                }

                archive.data.logs.push(newEntry);
                await db.archives.put(archive);
                await writeLogToWorldBook(archiveName, archive.data.logs);
            } catch (e) { console.error("保存日志到数据库失败:", e); }
        }

        async function writeLogToWorldBook(archiveName, logEntries) {
            if (!window.parent || !window.parent.TavernHelper) { console.warn("无法访问父窗口TavernHelper，跳过写入世界书。"); return false; }
            try {
                const primaryLorebook = await window.parent.TavernHelper.getCurrentCharPrimaryLorebook();
                if (!primaryLorebook) { console.warn("未找到当前角色的主世界书，无法写入日志。"); return false; }
                const fullLogContent = logEntries.map(log => `【${new Date(log.timestamp).toLocaleString()}】\n${log.content}`).join('\n\n---\n\n');
                const entries = await window.parent.TavernHelper.getLorebookEntries(primaryLorebook);
                const existingEntry = entries.find(e => e.comment === archiveName);
                if (existingEntry) {
                    const updatedEntry = { ...existingEntry, content: fullLogContent };
                    await window.parent.TavernHelper.setLorebookEntries(primaryLorebook, [updatedEntry]);
                } else {
                    const newEntry = { comment: archiveName, content: fullLogContent, enabled: true, keys: [] };
                    await window.parent.TavernHelper.createLorebookEntries(primaryLorebook, [newEntry]);
                }
                return true;
            } catch (e) { console.error("写入世界书时发生错误:", e); return false; }
        }

function getLogsForContext(allLogs) {
    const openingLog = allLogs.find(log => log.content.includes('<h4>命运初动 星辰回响</h4>')) || null;
    const chatLogs = allLogs.filter(log => !log.content.includes('<h4>命运初动 星辰回响</h4>'));
    const summaryLogs = allLogs.filter(log => log.content.startsWith('[过往篇章:'));

    if (summaryConfig.segmentedMemoryEnabled) {
        const allChatLogs = chatLogs.filter(log => log.type === 'user' || log.type === 'ai').sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
        const totalChatLogs = allChatLogs.length;

        const chatLayers = summaryConfig.segmentedChatLayers || 5;
        const largeSummaryStart = summaryConfig.segmentedLargeSummaryStart || 25;
        const recentLogsCount = chatLayers * 2;

        const splitIndex = Math.max(0, totalChatLogs - recentLogsCount);
        const olderLogs = allChatLogs.slice(0, splitIndex);
        const recentLogs = allChatLogs.slice(splitIndex);

        const logsForPrompt = [];
        if (openingLog) logsForPrompt.push(openingLog);
        logsForPrompt.push(...summaryLogs);

        const totalAiLogs = allChatLogs.filter(log => log.type === 'ai').length;
        let olderAiLogCounter = 0;

        olderLogs.forEach(log => {
            if (log.type === 'ai') {
                const reverseAiIndex = totalAiLogs - olderAiLogCounter - 1;
                if (largeSummaryStart > 0 && reverseAiIndex >= largeSummaryStart) {
                    logsForPrompt.push({ ...log, content: log.largeSummary || log.smallSummary || log.content });
                } else {
                    logsForPrompt.push({ ...log, content: log.smallSummary || log.content });
                }
                olderAiLogCounter++;
            } else {
                logsForPrompt.push(log);
            }
        });

        logsForPrompt.push(...recentLogs);

        return {
            openingLog,
            summaryLogs,
            hiddenChatLogs: [],
            visibleChatLogs: allChatLogs,
            logsForPrompt: logsForPrompt
        };
    }

    let nonSummaryChatLogs = allLogs.filter(log => !log.content.startsWith('[过往篇章:') && !log.content.includes('<h4>命运初动 星辰回响</h4>'));
    let hiddenChatLogs = [];
    let visibleChatLogs = [];
    let hiddenIndices = new Set();

    if (regexConfig.autoHideSummarized) {
        const lastSummaryIndex = allLogs.findLastIndex(log => log.content.startsWith('[过往篇章:'));
        if (lastSummaryIndex !== -1) {
            for(let i = 0; i < lastSummaryIndex; i++) {
                if (!allLogs[i].content.startsWith('[过往篇章:') && !allLogs[i].content.includes('<h4>命运初动 星辰回响</h4>')) {
                    hiddenIndices.add(allLogs[i].id);
                }
            }
        }
    }

    if (regexConfig.fixedHideRange) {
        const [start, end] = regexConfig.fixedHideRange.split('-').map(Number);
        if (!isNaN(start) && !isNaN(end) && start > 0 && end >= start) {
            for (let i = start - 1; i < end; i++) {
                if (nonSummaryChatLogs[i]) {
                    hiddenIndices.add(nonSummaryChatLogs[i].id);
                }
            }
        }
    }

    if (regexConfig.contextLimit > 0 && !regexConfig.autoHideSummarized && !regexConfig.fixedHideRange) {
        if (nonSummaryChatLogs.length > regexConfig.contextLimit) {
            const toHideCount = nonSummaryChatLogs.length - regexConfig.contextLimit;
            for (let i = 0; i < toHideCount; i++) {
                hiddenIndices.add(nonSummaryChatLogs[i].id);
            }
        }
    }

    nonSummaryChatLogs.forEach(log => {
        if (hiddenIndices.has(log.id)) {
            hiddenChatLogs.push(log);
        } else {
            visibleChatLogs.push(log);
        }
    });

    const logsForPrompt = [
        ...(openingLog ? [openingLog] : []),
        ...summaryLogs,
        ...visibleChatLogs
    ].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    return {
        openingLog,
        summaryLogs,
        hiddenChatLogs,
        visibleChatLogs,
        logsForPrompt
    };
}
        function calculateEquipmentBonuses() {
            const bonuses = {};
            Object.keys(CREATION_CONFIG.ATTRIBUTES).forEach(key => bonuses[key] = 0);
            const equipment = [
                ...(currentPlayerData.weapon || []),
                ...(currentPlayerData.armor || []),
                ...(currentPlayerData.accessory || []),
                ...(currentPlayerData.relic || []),
            ];
            equipment.forEach(item => {
                if (!item) return;
                const effects = parseItemEffect(item.effect);
                for (const attr in effects) {
                    if (bonuses.hasOwnProperty(attr)) {
                        bonuses[attr] += effects[attr];
                    }
                }
            });
            return bonuses;
        }

        function calculateNpcEquipmentBonuses(npcRow) {
            const bonuses = {};
            if (!npcRow || !currentState['1']) return bonuses;

            const npcId = npcRow['0'];
            const npcItems = Object.values(currentState['1']).filter(item => item['8'] === npcId && item['6']);

            npcItems.forEach(item => {
                if (item && item['4']) {
                    const effects = parseItemEffect(item['4']);
                    for (const attr in effects) {
