                        if (op.data['9'] && op.id === 'B1') {
                            const oldRemarks = parseRemarksString(targetChar['9']);
                            const newRemarks = parseRemarksString(op.data['9']);
                            if (newRemarks.money && newRemarks.money !== oldRemarks.money) {
                                const moneyChange = parseInt(newRemarks.money) - (parseInt(oldRemarks.money) || 0);
                                outcomeDetails.push(`<strong>${targetName}</strong> 秘银币 ${moneyChange > 0 ? '+' : ''}${moneyChange}`);
                            }
                        }
                    }
