                                 let costValue = 0;
                                 if (valueStr.includes('%')) {
                                     const percentage = parseInt(valueStr);
                                     costValue = Math.floor(maxMP * (percentage / 100));
                                 } else {
                                     costValue = parseInt(valueStr);
                                 }
                                 if (!isNaN(costValue) && currentMP >= costValue) {
                                     const newMP = currentMP - costValue;
                                     casterRow['7'] = `${newMP}|${maxMP}`;
                                     outcomeDetails.push(`<strong>${casterName}</strong> MP: ${currentMP} → ${newMP} (-${costValue})`);
                                 }
                             } else if (type === 'HP' && casterRow['6']) {
                                 const [currentHP, maxHP] = casterRow['6'].split('|').map(Number);
                                 const costValue = parseInt(valueStr);
                                 if (!isNaN(costValue)) {
                                     const newHP = currentHP - costValue;
                                     casterRow['6'] = `${newHP}|${maxHP}`;
                                     outcomeDetails.push(`<strong>${casterName}</strong> HP: ${currentHP} → ${newHP}`);
                                 }
                             }
                         });
                    }
                    if (isSuccess) {
                        let [level, currentXp] = (skill['4'] || '1|0').split('|').map(Number);
