        async function handleRegenerate(targetLogId) {
            const archive = await db.archives.get(currentArchiveName);
            if (!archive) return;

            let logs = archive.data.logs;
            const targetLogIndex = logs.findIndex(log => log.id === targetLogId);

            if (targetLogIndex === -1) {
                await showCustomAlert('没有可重新生成的目标。');
                return;
            }

            let lastUserLogIndex = -1;
            for (let i = targetLogIndex; i >= 0; i--) {
                if (logs[i].type === 'user') {
                    lastUserLogIndex = i;
                    break;
                }
            }

            if (lastUserLogIndex === -1) {
                await showCustomAlert('找不到对应的用户输入进行重新生成。');
                return;
            }

            const logsToKeep = logs.slice(0, lastUserLogIndex + 1);
            const lastLogWithState = [...logs.slice(0, lastUserLogIndex + 1)].reverse().find(log => log.stateSnapshot);

            if (!lastLogWithState) {
                 await showCustomAlert('致命错误：找不到可回溯的快照。');
                 return;
            }

            try {
                const snapshotObject = JSON.parse(lastLogWithState.stateSnapshot);
                const stateToLoad = snapshotObject.currentState ? snapshotObject : { currentState: snapshotObject };

                if (lastLogWithState.achievementsSnapshot) {
                    stateToLoad.achievements = JSON.parse(lastLogWithState.achievementsSnapshot);
                } else if (snapshotObject.achievements) {
                    stateToLoad.achievements = snapshotObject.achievements;
                }

                const lastLogWithPoints = [...logs.slice(0, lastUserLogIndex + 1)].reverse().find(log => log.attributePointsSnapshot !== undefined);
                await dbSet(`ATTRIB_POINTS_${currentArchiveName}`, lastLogWithPoints ? lastLogWithPoints.attributePointsSnapshot : 0);

                await loadState(stateToLoad);

                archive.data.state = stateToLoad;

            } catch(e) {
                await showCustomAlert('回溯状态失败，快照数据可能已损坏。');
                return;
            }

            archive.data.logs = logsToKeep;
            await db.archives.put(archive);
            await saveCurrentState();

            const lastUserLog = logsToKeep[lastUserLogIndex];
            const messageToSend = lastUserLog.content.startsWith('> ') ? lastUserLog.content.substring(2) : lastUserLog.content;

            loadChatHistory(logsToKeep);
            await sendMessage(messageToSend, true);
        }

        function parseAIResponse(rawResponse) {
            let content = rawResponse;

            content = content.replace(/<(?:think|thinking|Think|Thinking|tableThink)>[\s\S]*?<\/(?:think|thinking|Think|Thinking|tableThink)>/gi, '');
            content = content.replace(/\[finire\]\n?/g, '');

            let tableEditContent = '';
            const tableEditRegex = /<tableEdit>([\s\S]*?)<\/tableEdit>/g;

            content = content.replace(tableEditRegex, (match, innerContent) => {
                const commandRegex = /(updateRow|insertRow|deleteRow|addWorldEvent|addSmallSummary|addLargeSummary)\s*\([\s\S]*?\)/g;
                let commands = innerContent.match(commandRegex);
                if (commands) {
                    tableEditContent += commands.join(' ') + ' ';
                }
                return '';
            });

            let branchContent = null;
            const extractBranchOptions = (tag) => {
                const match = content.match(new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`));
                if (!match) return [];
                if (tag === 'branches') {
                    branchContent = match[0];
                }
                const optionRegex = /\[(.*?)\]/g;
                let option;
                const options = [];
                while ((option = optionRegex.exec(match[1])) !== null) {
                    options.push(option[1]);
                }
                content = content.replace(match[0], '');
                return options;
            };

            const branchOptions = extractBranchOptions('branches');
            const successBranchOptions = extractBranchOptions('branch_success');
            const failBranchOptions = extractBranchOptions('branch_fail');

            const picGenRegex = /<pic[^>]*\sprompt="([^"]*)"[^>]*?>/g;
            if (chatBackgroundSettings.autoImageGen) {
                let picMatch;
                while ((picMatch = picGenRegex.exec(content)) !== null) {
                    const prompt = picMatch[1];
                    if (prompt) {
                        handleAIGenRequest(prompt, true);
                    }
                }
            }
            content = content.replace(picGenRegex, '');

            content = processTextWithRules(content, PLACEMENT_MAP.AI_OUTPUT, 'chain');

            content = processTextWithRules(content, PLACEMENT_MAP.AI_OUTPUT, 'regular');

            return {
                tableEditCommands: tableEditContent.trim(),
                branchOptions,
                successBranchOptions,
                failBranchOptions,
                contentBeforeProcessing: content.trim(),
                branchContent: branchContent
            };
        }

        function parseRegexString(regexString) {
            const lastSlash = regexString.lastIndexOf('/');
            if (regexString.startsWith('/') && lastSlash > 0) {
                const pattern = regexString.substring(1, lastSlash);
                const flags = regexString.substring(lastSlash + 1);
                return { pattern, flags };
            }
            return { pattern: regexString, flags: 'g' };
        }

        function processTextWithRules(text, scope, type) {
            let processedText = text;
            const rules = type === 'chain' ? (regexConfig.chainRules || []) : (regexConfig.rules || []);

            rules.forEach(rule => {
                if (!rule.disabled && rule.placement && rule.placement.includes(scope)) {
                    try {
                        const { pattern, flags } = parseRegexString(rule.findRegex);
                        const regex = new RegExp(pattern, flags);
                        processedText = processedText.replace(regex, rule.replaceString);
                    } catch (e) {
                        console.error(`无效的${type}正则表达式: ${rule.findRegex}`, e);
                    }
                }
            });

            return processedText;
        }

        async function updateUI(rawResponse, initialState) {
            newTaskAdded = false;

            const { tableEditCommands, branchOptions, successBranchOptions, failBranchOptions, contentBeforeProcessing, branchContent } = parseAIResponse(rawResponse);

            let { delta, smallSummary, largeSummary } = parseTableEditCommands(tableEditCommands);

            const changesResult = await applyChanges(initialState, delta);
            currentState = changesResult.state;

            syncStateFromTables();

            let processedResult;
            try {
                processedResult = await processBrackets(contentBeforeProcessing, { success: successBranchOptions, fail: failBranchOptions });
            } catch (error) {
                addMessageToLog({ content: `[系统错误] 检定标签解析失败: ${error.message}。请检查AI回复格式或控制台。` }, 'error');
                sendMessageButton.disabled = false;
                return;
            }

            const { html: finalContent, firstCheckResult } = processedResult;
            const finalSuccessBranches = processedResult.conditionalBranches.success;
            const finalFailBranches = processedResult.conditionalBranches.fail;

            if (processedResult.summary) {
                const chosenSummary = processedResult.summary;
                if (smallSummary === null) {
                   const { smallSummary: newSmall } = parseTableEditCommands(`addSmallSummary(${JSON.stringify(chosenSummary)})`);
                   if (newSmall) smallSummary = newSmall;
                } else {
                    smallSummary += ` [判定结果] ${chosenSummary}`;
                }
            }

            const achievementsChanged = await checkAchievements(finalContent);

            if (achievementsChanged) {
                const archive = await db.archives.get(currentArchiveName);
                if (archive) {
                    archive.data.state.achievements = currentState.achievements;
                    await db.archives.put(archive);
                }
            }

            await checkTaskCompletion();

            const archiveForSnapshot = await db.archives.get(currentArchiveName);
            const stateToSnapshot = JSON.parse(JSON.stringify(archiveForSnapshot.data.state));
            stateToSnapshot.currentState = currentState;
            if (stateToSnapshot.npcAvatars) {
                delete stateToSnapshot.npcAvatars;
            }

            const achievementsSnapshot = stateToSnapshot.achievements;
            const attributePointsSnapshot = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;

            const generateSimpleId = () => `${Date.now()}${Math.random().toString(36).substr(2, 5)}`;
            const newLogEntryId = generateSimpleId();
            let newLogEntry = null;

            if (finalContent || branchContent || processedResult.html.includes('<branch_success>') || processedResult.html.includes('<branch_fail>')) {
                let finalBranchContent = branchContent || '';

                const successMatch = processedResult.html.match(/<branch_success>([\s\S]*?)<\/branch_success>/);
                if (successMatch) {
                    finalBranchContent += successMatch[0];
                }

                const failMatch = processedResult.html.match(/<branch_fail>([\s\S]*?)<\/branch_fail>/);
                if (failMatch) {
                    finalBranchContent += failMatch[0];
                }

                newLogEntry = { 
                    id: newLogEntryId, 
                    timestamp: new Date().toISOString(), 
                    content: finalContent,
                    branchContent: finalBranchContent.trim() || null,
                    stateSnapshot: JSON.stringify(stateToSnapshot),
                    achievementsSnapshot: achievementsSnapshot ? JSON.stringify(achievementsSnapshot) : null,
                    attributePointsSnapshot: attributePointsSnapshot,
                    type: 'ai'
                };
            }

            if (summaryConfig.segmentedMemoryEnabled) {
                if (smallSummary !== null || largeSummary !== null) {
                    if (newLogEntry) {
                        newLogEntry.smallSummary = smallSummary || '';
                        newLogEntry.largeSummary = largeSummary || '';
                    }
                } else if (newLogEntry && !rawResponse.includes('【check|')) {
                    newLogEntry.smallSummary = "小总结";
                    newLogEntry.largeSummary = "大总结";
                    await saveToLog(currentArchiveName, newLogEntry);
                    openManualSegmentedMemoryEditor(newLogEntryId);
                }
            }

            updateLocationInWorldBook();

            if (newLogEntry) {
                await saveToLog(currentArchiveName, newLogEntry);
            }

            await saveCurrentState();

            if (newLogEntry) {
                if (regexConfig.enableTypewriterOutput) {
                    const newEntryElement = createLogEntryElement(newLogEntry, 'ai');
                    newEntryElement.innerHTML = '';
                    mainContentArea.appendChild(newEntryElement);

                    await typewriterStream(newEntryElement, newLogEntry.content, () => {
                        mainContentArea.scrollTop = mainContentArea.scrollHeight;
                    });
                } else {
                    addMessageToLog(newLogEntry, 'ai');
                }
            }

            if (newTaskAdded) {
                const btn = document.getElementById('view-tasks-btn');
                if (!btn.querySelector('.red-dot')) {
                    const dot = document.createElement('span');
                    dot.className = 'red-dot';
                    btn.appendChild(dot);
                }
                if (tasksOverlay.classList.contains('visible')) {
                    renderAllTaskLists();
                }
            }

            renderInventory(inventoryItems);
            updateAvatar(currentPlayerData);

            if (firstCheckResult === true && finalSuccessBranches.length > 0) {
                updateBranchingOptions(finalSuccessBranches);
            } else if (firstCheckResult === false && finalFailBranches.length > 0) {
                updateBranchingOptions(finalFailBranches);
            } else if (branchOptions.length > 0) {
                updateBranchingOptions(branchOptions);
            } else {
                updateBranchingOptions([]);
            }

            checkPlayerDeath();
            await runAutoSummaryCheck();
        }

