        async function slimDownArchiveCompletely(archiveName) {
            showLoading('正在彻底瘦身存档，请稍候...');
            try {
                const archive = await db.archives.get(archiveName);
                if (!archive) return;

                let mainStateChanged = false;
                let logsChanged = false;
                let combinedNpcAvatars = {};

                const existingAvatars = await dbGet(`${NPC_AVATARS_KEY}_${archiveName}`) || {};
                Object.assign(combinedNpcAvatars, existingAvatars);

                if (archive.data.state) {
                    if (archive.data.state.npcAvatars) {
                        Object.assign(combinedNpcAvatars, archive.data.state.npcAvatars);
                        delete archive.data.state.npcAvatars;
                        mainStateChanged = true;
                    }
                    if (archive.data.state.currentState && archive.data.state.currentState.npcAvatars) {
                        Object.assign(combinedNpcAvatars, archive.data.state.currentState.npcAvatars);
                        delete archive.data.state.currentState.npcAvatars;
                        mainStateChanged = true;
                    }
                }

                for (const log of archive.data.logs) {
                    if (log.stateSnapshot) {
                        try {
                            const snapshotObject = JSON.parse(log.stateSnapshot);
                            let snapshotModified = false;

                            if (snapshotObject.npcAvatars) {
                                Object.assign(combinedNpcAvatars, snapshotObject.npcAvatars);
                                delete snapshotObject.npcAvatars;
                                snapshotModified = true;
                            }

                            if (snapshotObject.currentState && snapshotObject.currentState.npcAvatars) {
                                Object.assign(combinedNpcAvatars, snapshotObject.currentState.npcAvatars);
                                delete snapshotObject.currentState.npcAvatars;
                                snapshotModified = true;
                            }

                            if (snapshotModified) {
                                log.stateSnapshot = JSON.stringify(snapshotObject);
                                logsChanged = true;
                            }
                        } catch (e) {
                            console.warn(`Skipping malformed snapshot in log ${log.id} during slim down.`);
                        }
                    }
                }

                if (mainStateChanged || logsChanged) {
                    if (Object.keys(combinedNpcAvatars).length > 0) {
                         await dbSet(`${NPC_AVATARS_KEY}_${archiveName}`, combinedNpcAvatars);
                    }
                    await db.archives.put(archive);
                    console.log(`Archive '${archiveName}' has been completely slimmed down.`);
                }
            } catch (error) {
                console.error("Error during complete archive slim down:", error);
                await showCustomAlert('存档瘦身过程中发生错误。');
            } finally {
                hideLoading();
            }
        }

