            const itemRow = currentState['1'][itemId];
            if (!itemRow) return;

            const currentQuantity = parseInt(itemRow['5']);

            if (type === 'sell') {
                const value = parseInt(itemRow['7'] || 0);
                const playerRow = currentState['0']['B1'];
                const newMoney = (parseInt(playerRow['18']) || 0) + (value * quantity);
                playerRow['18'] = newMoney;
                showDanmaku(`出售成功，获得 ${value * quantity} 秘银币`, 'item');
            }

            if (currentQuantity <= quantity) {
                delete currentState['1'][itemId];
            } else {
                itemRow['5'] = (currentQuantity - quantity).toString();
            }

            await saveCurrentState();
            syncStateFromTables();
            renderInventory(inventoryItems);
            renderPlayerAttributes(currentPlayerData);
