        function showCustomDialog(options) {
            return new Promise((resolve) => {
                const { title, message, inputType = 'none', defaultValue = '', buttons } = options;

                const modal = document.getElementById('custom-dialog-modal');
                modal.innerHTML = `
                    <h4 id="custom-dialog-title"></h4>
                    <div class="modal-content">
                        <p id="custom-dialog-message"></p>
                        <input type="text" id="custom-dialog-input" class="settings-section hidden">
                    </div>
                    <div id="custom-dialog-buttons" class="modal-footer"></div>
                `;

                modal.querySelector('#custom-dialog-title').textContent = title;
                modal.querySelector('#custom-dialog-message').innerHTML = message;
                const inputEl = modal.querySelector('#custom-dialog-input');
                const buttonsEl = modal.querySelector('#custom-dialog-buttons');

                if (inputType === 'text') {
                    inputEl.type = 'text';
                    inputEl.value = defaultValue;
                    inputEl.classList.remove('hidden');
                }

                buttons.forEach(btnConfig => {
                    const button = document.createElement('button');
                    button.textContent = btnConfig.text;
                    button.className = 'major-action-button';
                    if (btnConfig.style === 'danger') {
