        function showMonsterDetail(monster) {
            const overlay = document.getElementById('monster-detail-overlay');
            const contentEl = document.getElementById('monster-detail-content');
            if (!overlay || !contentEl) return;

            const [name, category] = (monster['1'] || '|').split('|');
            const [job, rarity] = (monster['2'] || '|').split('|');
            const [currentHP, maxHP] = (monster['6'] || '0|0').split('|').map(Number);
            const [currentMP, maxMP] = (monster['7'] || '0|0').split('|').map(Number);
