                            ${createGridItem('样貌', char.appearance)}
                            ${createGridItem('身段', char.figure)}
                            ${createGridItem('穿着', char.attire)}
                            ${createGridItem('当前动作', char.action)}
                            ${createGridItem('内心想法', char.motive)}
                            ${createGridItem('所在地点', `${char.location || '未知'} / ${char.detailedLocation || '未知'}`)}
                        </div>`;
                    container.innerHTML = createSection('<i class="fas fa-user-circle"></i> 基本信息', statusContent, true) + 
                                          createSection('<i class="fas fa-scroll"></i> 背景故事', `<p>${char.background || '暂无背景信息。'}</p>`, true);
                    break;
                case 'attributes':
                    let attributesContent;
                    let attrs = {};
                    if (char.attributes && char.attributes.startsWith('{')) {
                        try { attrs = JSON.parse(char.attributes); } catch(e) { attrs = { error: "格式错误" }; }
                    }

                    if (attrs.error) {
                        attributesContent = '<p style="text-align:center; opacity:0.7;">属性信息格式错误。</p>';
                    } else {
                        const npcRowForBonus = currentState['0'][char.id];
                        const equipmentBonuses = calculateNpcEquipmentBonuses(npcRowForBonus);

                        let attributesHtml = Object.keys(CREATION_CONFIG.ATTRIBUTES).map(key => {
