                                bonusHtml = ` <span class="attr-penalty">(${bonusValue})</span>`;
                            }
                            return `<div class="attribute-display-item"><span class="attr-display-label">${key}</span><span class="attr-display-value">${baseValue}${bonusHtml}</span></div>`;
