            const reader = new FileReader();
            reader.onload = async (e) => {
                try {
                    const importedLocations = JSON.parse(e.target.result);
                    if (!Array.isArray(importedLocations)) {
                        throw new Error('地图地标文件格式无效，应为一个数组。');
                    }

                    if (await showCustomConfirm('确定要将此地标配置导入到当前活动的存档吗？这将覆盖当前存档的地标数据。')) {
                        const archive = await db.archives.get(currentArchiveName);
                        if (archive) {
                            archive.data.state.locations = importedLocations;
                            await db.archives.put(archive);
                            currentLocationsData = importedLocations;
                            await showCustomAlert('地标配置已成功导入！');
                            mapArchiveSelectionOverlay.classList.remove('visible');
                        } else {
                            await showCustomAlert('导入失败：没有活动的存档。');
                        }
                    }
                } catch (err) {
                    await showCustomAlert(`导入失败: ${err.message}`);
                } finally {
                    event.target.value = '';
                }
            };
            reader.readAsText(file);
        });

