        async function deleteMapMarker() {
            if (!activeMapMarker) return;
            const index = parseInt(activeMapMarker.dataset.index);
            if (index >= 0 && index < mapEditorLocations.length) {
                if (await showCustomConfirm(`确定要删除地标 "${mapEditorLocations[index].name}" 吗？`)) {
