        let isDragging = false;
        let dragOffsetX = 0;
        let dragOffsetY = 0;

        function handleMarkerMouseDown(e) {
            if (e.button !== 0 || isAddingLocationMode) return;
            e.preventDefault();
            activeMapMarker = e.currentTarget;
            activeMapMarker.classList.add('dragging');

            const rect = activeMapMarker.getBoundingClientRect();
            dragOffsetX = e.clientX - rect.left;
            dragOffsetY = e.clientY - rect.top;

            isDragging = true;
        }

        function handleEditorMouseMove(e) {
            if (!isDragging || !activeMapMarker) return;
            e.preventDefault();

            const mapContainer = document.getElementById('map-editor-viewport');
            const mapRect = mapContainer.getBoundingClientRect();
            let x = e.clientX - mapRect.left - dragOffsetX + mapContainer.scrollLeft;
            let y = e.clientY - mapRect.top - dragOffsetY + mapContainer.scrollTop;

            const imgRect = document.getElementById('map-editor-img').getBoundingClientRect();
            x = Math.max(0, Math.min(x, imgRect.width));
            y = Math.max(0, Math.min(y, imgRect.height));

            activeMapMarker.style.left = `${(x / imgRect.width) * 100}%`;
            activeMapMarker.style.top = `${(y / imgRect.height) * 100}%`;
        }

        function handleEditorMouseUp(e) {
            if (!isDragging || !activeMapMarker) return;
            e.preventDefault();

            const index = parseInt(activeMapMarker.dataset.index);
            if (index >= 0 && index < mapEditorLocations.length) {
                const location = mapEditorLocations[index];
                if (location.marker) {
                    location.marker.left = activeMapMarker.style.left;
                    location.marker.top = activeMapMarker.style.top;
                }
            }

            activeMapMarker.classList.remove('dragging');
            isDragging = false;
            activeMapMarker = null;
        }

        function handleMarkerContextMenu(e) {
            e.preventDefault();
            activeMapMarker = e.currentTarget;
            mapMarkerContextMenu.classList.remove('hidden');
            positionMenu(mapMarkerContextMenu, e);
        }

        document.getElementById('map-editor-viewport').addEventListener('mousemove', handleEditorMouseMove);
        document.getElementById('map-editor-viewport').addEventListener('mouseup', handleEditorMouseUp);
        document.getElementById('map-editor-viewport').addEventListener('mouseleave', handleEditorMouseUp);

        document.getElementById('map-editor-viewport').addEventListener('click', async (event) => {
            if (!isAddingLocationMode || event.target.closest('.map-location-marker')) return;

            const viewport = document.getElementById('map-editor-viewport');
            const pannable = document.getElementById('map-editor-pannable');
            const viewportRect = viewport.getBoundingClientRect();

            const scale = parseFloat(pannable.dataset.scale) || 1;
            const panX = parseFloat(pannable.dataset.panX) || 0;
            const panY = parseFloat(pannable.dataset.panY) || 0;

            const clickInViewportX = event.clientX - viewportRect.left;
            const clickInViewportY = event.clientY - viewportRect.top;

            const worldX = (clickInViewportX - panX) / scale;
            const worldY = (clickInViewportY - panY) / scale;

            const leftPercent = (worldX / pannable.offsetWidth) * 100;
            const topPercent = (worldY / pannable.offsetHeight) * 100;

            const locationName = await showCustomPrompt("请输入新地点的名称:", "");
            if (locationName && locationName.trim() !== "") {
                mapEditorLocations.push({
                    name: locationName.trim(),
                    type: 'point',
                    marker: {
                        top: `${topPercent.toFixed(2)}%`,
                        left: `${leftPercent.toFixed(2)}%`
                    }
                });
                renderMapLocations(document.getElementById('map-editor-locations-container'), mapEditorLocations, true);
            }

            isAddingLocationMode = false;
            viewport.classList.remove('add-mode');
        });

        async function writeMapToWorldBook(archiveName, locationsData) {
            if (!window.parent || !window.parent.TavernHelper) { console.warn("无法访问父窗口TavernHelper，跳过写入世界书。"); return false; }
            try {
                const primaryLorebook = await window.parent.TavernHelper.getCurrentCharPrimaryLorebook();
                if (!primaryLorebook) { console.warn("未找到当前角色的主世界书，无法写入地图。"); return false; }

                const formatLocations = (realm, locations) => {
                    if (!locations || locations.length === 0) return '';
                    const mainLocation = locations.find(loc => currentPlayerData.location.includes(loc.name));
                    const locationStrings = locations.map(loc => {
                        if (loc.name === mainLocation?.name && currentPlayerData.detailedLocation && currentPlayerData.detailedLocation !== '未知') {
                            return `${loc.name}(${currentPlayerData.detailedLocation})`;
                        }
                        return loc.name;
                    });
                    return `${realm}地点: ${locationStrings.join(', ')}`;
                };

                const humanLocationsStr = formatLocations('人界', locationsData.human);
                const spiritLocationsStr = formatLocations('灵界', locationsData.spirit);
                const fullMapContent = [humanLocationsStr, spiritLocationsStr].filter(Boolean).join(' | ');

                const entries = await window.parent.TavernHelper.getLorebookEntries(primaryLorebook);
                const existingEntry = entries.find(e => e.comment === MAP_LORE_ENTRY_NAME);

                const entryData = {
                    content: fullMapContent,
                    keys: [],
                    insertion_order: 4,
                    enabled: true
                };

                if (existingEntry) {
                    const updatedEntry = { ...existingEntry, ...entryData };
                    await window.parent.TavernHelper.setLorebookEntries(primaryLorebook, [updatedEntry]);
                } else {
                    const newEntry = { comment: MAP_LORE_ENTRY_NAME, ...entryData };
                    await window.parent.TavernHelper.createLorebookEntries(primaryLorebook, [newEntry]);
                }
                return true;
            } catch (e) { console.error("写入地图到世界书时发生错误:", e); return false; }
        }

async function showSummaryList() {
