            XP_FORMULA: {
                base: 5,
                growthFactor: 2,
                tierMultiplier: (tier) => 1 + (tier * 0.2)
            },
            DICE_UPGRADE_PATH: ['d4', 'd6', 'd8', 'd10', 'd12', 'd20'],
            EFFECT_GROWTH_PER_LEVEL: (effect, level, tier) => {
                const growth = { flat: 0, diceCount: 0, diceType: effect['1'] };
                if (level === 1) return growth;

                const flatGrowth = 1 + Math.floor(tier / 2);
                growth.flat = (level - 1) * flatGrowth;

                const diceUpgradeLevels = Math.floor((level - 1) / 4);
                if (diceUpgradeLevels > 0 && effect['1']) {
                    const currentDiceIndex = SKILL_SYSTEM_CONFIG.DICE_UPGRADE_PATH.indexOf(effect['1'].split('d')[1]);
                    if (currentDiceIndex > -1) {
                        const newDiceIndex = Math.min(SKILL_SYSTEM_CONFIG.DICE_UPGRADE_PATH.length - 1, currentDiceIndex + diceUpgradeLevels);
                        growth.diceType = `${effect['1'].split('d')[0]}d${SKILL_SYSTEM_CONFIG.DICE_UPGRADE_PATH[newDiceIndex].substring(1)}`;
                    }
                }

                const diceCountLevels = Math.floor((level - 1) / 3);
                growth.diceCount = diceCountLevels;

                return growth;
            },
            COST_GROWTH: {
                'MP': 2, 'HP': 1, '体力': 0.5
            },
            SAVE_DC_FORMULA: (caster, attribute) => {
                const attrValue = caster.detailedAttributes[attribute] || 10;
                return 8 + Math.floor((attrValue - 10) / 2);
            }
        };

        function isPointInPolygon(point, polygon) {
            let x = point.x, y = point.y;
            let inside = false;
            for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
                let xi = polygon[i].x, yi = polygon[i].y;
                let xj = polygon[j].x, yj = polygon[j].y;
                let intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
                if (intersect) inside = !inside;
            }
            return inside;
        }

