        function calculateSkillCost(skillData, level) {
            if (!skillData['7']) return '无';

            return skillData['7'].split(';').map(part => {
                const [type, baseValueStr] = part.split(':');
                if (!type || !baseValueStr) return '';

                if (baseValueStr.includes('%')) {
                    return `${baseValueStr} ${type}`;
                }

                if (type === 'MP' || type === 'HP' || type === '体力') {
                    if (baseValueStr.includes('d')) {
                        return `${baseValueStr} ${type}`;
                    } else {
                        const baseCost = parseInt(baseValueStr);
                        const perLevelCost = SKILL_SYSTEM_CONFIG.COST_GROWTH[type] || 0;
                        const finalCost = baseCost + ((level - 1) * perLevelCost);
                        return `${finalCost} ${type}`;
                    }
                } else {
                    const item = currentState['1'] ? currentState['1'][type] : null;
                    const itemName = item ? item['1'] : '未知物品';
                    return `${itemName} x ${baseValueStr}`;
                }
            }).filter(Boolean).join(' + ') || '无';
        }

        function calculateSkillXPForLevel(level, tier) {
            const { base, growthFactor, tierMultiplier } = SKILL_SYSTEM_CONFIG.XP_FORMULA;
            const requiredXP = base + ((level - 1) * growthFactor);
            return Math.floor(requiredXP * tierMultiplier(tier));
        }

        function calculatePetXPForLevel(level) {
            const baseXP = 50;
            const exponent = 1.8;
            const linearGrowth = 25;
            return Math.floor(baseXP * Math.pow(level, exponent) + (level * linearGrowth));
        }

        function getSkillMaxLevel(tier) {
            return SKILL_SYSTEM_CONFIG.TIER_TO_MAX_LEVEL[tier] || 1;
        }

