                case 2: renderStep2_Race(contentEl, navEl); break;
                case 3: renderStep3_Class(contentEl, navEl); break;
                case 4: renderStep3_Background(contentEl, navEl); break;
                case 5: renderStep4_Abilities(contentEl, navEl); break;
                case 6: renderStep5_Traits(contentEl, navEl); break;
                case 7: renderStep6_Guardian(contentEl, navEl); break;
                case 8: renderStep7_Birthplace(contentEl, navEl); break;
            }
