                let attributesHtml = '<h4>基础属性</h4><div class="char-info-grid" style="grid-template-columns: 1fr 1fr 1fr 1fr;">';
                for(const attr in data.base_attributes) {
                    attributesHtml += `<div class="label">${attr}:</div><div>${data.base_attributes[attr]}</div>`;
                }
                attributesHtml += '</div>';

                let traitsHtml = '';
                if (data.traits && data.traits.length > 0) {
                    traitsHtml = '<h4>种族天赋</h4>';
                    data.traits.forEach(trait => {
                        traitsHtml += `
                            <div style="margin-bottom: 10px;">
                                <strong>${trait.name} [${trait.rarity}]</strong>
                                <p style="font-size: 0.9em; margin: 2px 0 0 0; color: #ccc;">${trait.desc}<br><em>效果: ${trait.effects}</em></p>
                            </div>
                        `;
                    });
                }
                contentHtml = `${attributesHtml}<hr style="border-color: var(--separator-color);">${traitsHtml}`;

            } else if (type === 'class') {
                const data = CREATION_CONFIG.CLASSES[name];
                if (!data) return;
                title = `职业详情: ${name}`;

                let itemHtml = '<h4>初始道具</h4>';
                if (data.item && data.item !== '无') {
                    const itemMatch = data.item.match(/【(.*?)】/);
                    if (itemMatch) {
                        const [itemName, itemDesc, itemType, itemEffect] = itemMatch[1].split('|');
                        itemHtml += `
                            <div class="char-info-grid">
                                <div class="label">名称:</div><div>${itemName}</div>
                                <div class="label">类型:</div><div>${itemType}</div>
                                <div class="label">描述:</div><div>${itemDesc}</div>
                                <div class="label">效果:</div><div>${itemEffect}</div>
                            </div>
                        `;
                    }
                } else {
                    itemHtml += '<p>无特殊初始道具。</p>';
                }
                contentHtml = itemHtml;
            }

            showCustomDialog({
                title: title,
                message: contentHtml,
                buttons: [{ text: '关闭', value: () => true }]
            });
        }

