            contentEl.querySelectorAll('.randomize-batch-btn').forEach(btn => btn.addEventListener('click', handleRandomizeBatchTraits));
            contentEl.querySelector('#self-select-trait-btn')?.addEventListener('click', openSelfSelectTraitModal);
            contentEl.querySelector('#manage-custom-traits-btn')?.addEventListener('click', openCustomTraitManager);

            contentEl.querySelectorAll('.trait-card .trait-detail-btn').forEach(btn => {
