                async function handleRandomizeBatchTraits(event) {
            const count = parseInt(event.currentTarget.dataset.count);
            const traitCosts = { 1: 10, 2: 20, 3: 30, 4: 40, 5: 50 };
            const cost = traitCosts[count];

            if (calculateRemainingPoints() < cost) {
                await showCustomAlert('宿命点数不足，无法进行抽取！');
                return;
            }

            creationState.totalPoints -= cost;

            creationState.selectedTraits = [];

            const container = document.getElementById('trait-options-container');
            container.classList.add('animating');

            setTimeout(async () => {
                const newTraits = await generateRandomTraits(count);
                creationState.selectedTraits = newTraits;
                renderCreationStep();

                const contentEl = document.getElementById('creation-content');
                if (contentEl) {
                    contentEl.scrollTo({ top: 0, behavior: 'smooth' });
                }
            }, 250);
        }

        async function generateRandomTraits(count = 6) {
            const allTraits = [];
            for (const rarity in CREATION_CONFIG.TRAITS) {
                CREATION_CONFIG.TRAITS[rarity].forEach(trait => {
                    allTraits.push({ ...trait, rarity });
                });
            }

            const customTraits = await getCustomTraits();
            const activeCustomTraits = customTraits.filter(t => t.inPool);
            allTraits.push(...activeCustomTraits);

            const traits = [];
            const rarityWeights = { '负面状态': 10, '普通': 30, '稀有': 25, '史诗': 20, '传说': 10, '神迹': 5 };
            const totalWeight = Object.values(rarityWeights).reduce((sum, weight) => sum + weight, 0);

            const pickRarity = () => {
                let random = Math.random() * totalWeight;
                for (const rarity in rarityWeights) {
                    if (random < rarityWeights[rarity]) {
                        return rarity;
                    }
                    random -= rarityWeights[rarity];
                }
                return '普通';
            };

            while(traits.length < count) {
                const randRarity = pickRarity();
                const traitPool = allTraits.filter(t => t.rarity === randRarity);
                if (traitPool.length === 0) continue;

                const randTrait = traitPool[Math.floor(Math.random() * traitPool.length)];
                if (!traits.some(t => t.name === randTrait.name)) {
                    traits.push(randTrait);
                }
            }
            return traits;
        }

        async function openSelfSelectTraitModal() {
            if (creationState.selectedTraits.length > 0 && !creationState.isSelfSelectingTraits) {
                if (!await showCustomConfirm('自选天赋将会清空当前已抽取的天赋，是否继续？')) {
                    return;
                }
            } else {
                if (!await showCustomConfirm('进入自选天赋界面将会清空当前所有已选天赋，并重新开始选择。是否继续？')) {
                    return;
                }
            }

            creationState.selectedTraits = [];
            creationState.isSelfSelectingTraits = true;

            const overlay = document.getElementById('self-select-trait-overlay');
            overlay.innerHTML = `
                <div class="imprint-select-modal modal">
                    <button class="modal-close-btn">&times;</button>
                    <h4>自选天赋 (最多5个)</h4>
                    <div id="trait-select-tabs" class="modal-tabs">
                        <button class="tab-button active" data-tab="default">默认天赋</button>
                        <button class="tab-button" data-tab="custom">自定义天赋</button>
                    </div>
                    <div class="imprint-list-container">
                        <div id="default-traits-container" class="tab-content active"></div>
                        <div id="custom-traits-container" class="tab-content"></div>
                    </div>
                    <div class="imprint-selection-footer">
                        <div id="self-select-trait-details"></div>
                        <button id="confirm-self-select-trait-btn" class="major-action-button">确认选择</button>
                    </div>
                </div>
            `;

            const defaultContainer = overlay.querySelector('#default-traits-container');
            const customContainer = overlay.querySelector('#custom-traits-container');
            const detailsEl = overlay.querySelector('#self-select-trait-details');
            const confirmBtn = overlay.querySelector('#confirm-self-select-trait-btn');

            let tempSelected = [...creationState.selectedTraits];
            let currentCost = 0;

            const defaultTraits = [];
            for (const rarity in CREATION_CONFIG.TRAITS) {
                defaultTraits.push({ rarity, traits: CREATION_CONFIG.TRAITS[rarity] });
            }
            const customTraits = (await getCustomTraits()).filter(t => t.inPool);

            const renderList = (container, traitsData, isCustom = false) => {
                if (isCustom) {
                    if (traitsData.length === 0) {
                        container.innerHTML = `<p style="text-align:center; opacity:0.7; padding: 20px;">没有可用的自定义天赋，请先在管理器中创建并启用。</p>`;
                        return;
                    }
                    const list = traitsData.map(trait => {
                        const validationError = validateCustomTraitStructure(trait);
                        const cost = calculateCustomTraitCost(trait.bonus);
                        const displayCost = -cost;
                        const costText = displayCost > 0 ? `+${displayCost}` : displayCost;
                        const costClass = displayCost >= 0 ? 'bonus' : 'penalty';
                        const invalidClass = validationError ? 'invalid' : '';
                        const title = validationError ? `数据格式错误: ${validationError}` : trait.desc;
                        return `<li data-name="${trait.name}" data-rarity="${trait.rarity}" data-custom="true" data-cost="${cost}" class="${invalidClass}" title="${title}"><strong>${trait.name} [${trait.rarity}]</strong><p>${trait.desc} <span class="${costClass}">(${costText}点)</span></p></li>`;
                    }).join('');
                    container.innerHTML = `<ul class="imprint-list">${list}</ul>`;
                } else {
                    traitsData.forEach(({ rarity, traits }) => {
                        if (traits.length === 0) return;
                        const group = document.createElement('div');
                        group.className = 'imprint-rank-group';
                        const cost = CREATION_CONFIG.TRAIT_RARITIES[rarity].cost;
                        const displayCost = -cost;
                        const list = traits.map(trait => `<li data-name="${trait.name}" data-rarity="${rarity}" data-cost="${cost}" title="${trait.desc}"><strong>${trait.name}</strong><p>${trait.desc} <span class="penalty">(${displayCost}点)</span></p></li>`).join('');
                        group.innerHTML = `<h3 class="rank-title">${rarity}</h3><ul class="imprint-list">${list}</ul>`;
                        container.appendChild(group);
                    });
                }
            };

            renderList(defaultContainer, defaultTraits);
            renderList(customContainer, customTraits, true);

            const updateSelection = () => {
                currentCost = 0;
                overlay.querySelectorAll('li').forEach(li => {
                    const isSelected = tempSelected.some(t => t.name === li.dataset.name);
                    if (isSelected) {
                        currentCost += parseInt(li.dataset.cost);
                    }
                    li.classList.toggle('selected', isSelected);
                });

                const remainingPointsAfterSelection = calculateRemainingPoints() - currentCost;

                let costHtml = '';
                if (currentCost > 0) {
                    costHtml = `消耗 <span class="penalty">${currentCost}</span> 点`;
                } else if (currentCost < 0) {
                    costHtml = `返还 <span class="bonus">${-currentCost}</span> 点`;
                } else {
                    costHtml = '花费 0 点';
                }

                detailsEl.innerHTML = `已选: ${tempSelected.length}/5 | ${costHtml} | 结束后剩余: <span class="${remainingPointsAfterSelection >= 0 ? 'bonus' : 'penalty'}">${remainingPointsAfterSelection}</span>`;
                confirmBtn.disabled = remainingPointsAfterSelection < 0;
            };

            overlay.querySelectorAll('li').forEach(li => {
                li.addEventListener('click', () => {
                    if (li.classList.contains('invalid')) {
                        showCustomAlert(li.title);
                        return;
                    }

                    const traitName = li.dataset.name;
                    const selectedIndex = tempSelected.findIndex(t => t.name === traitName);

                    if (selectedIndex > -1) {
                        tempSelected.splice(selectedIndex, 1);
                    } else {
                        if (tempSelected.length >= 5) {
                            showCustomAlert('最多只能选择5个天赋！'); return;
                        }
                        const rarity = li.dataset.rarity;
                        const isCustom = li.dataset.custom === 'true';
                        const traitData = isCustom ? customTraits.find(t => t.name === traitName) : CREATION_CONFIG.TRAITS[rarity].find(t => t.name === traitName);
                        tempSelected.push({ ...traitData, rarity });
                    }
                    updateSelection();
                });
            });

            overlay.querySelectorAll('.tab-button').forEach(tab => {
                tab.addEventListener('click', () => {
                    overlay.querySelectorAll('.tab-button').forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    overlay.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
                    document.getElementById(`${tab.dataset.tab}-traits-container`).classList.add('active');
                });
            });

            confirmBtn.onclick = async () => {
                const finalCost = currentCost;
                const remainingPointsAfterSelection = calculateRemainingPoints() - finalCost;
                if (remainingPointsAfterSelection < 0) {
                    await showCustomAlert('宿命点数不足，无法确认选择！');
                    return;
                }

                creationState.selectedTraits = tempSelected;

                overlay.classList.remove('visible');
                renderCreationStep();
            };

            overlay.querySelector('.modal-close-btn').onclick = () => overlay.classList.remove('visible');
            overlay.classList.add('visible');
            updateSelection();
        }

        function showTraitDetail(trait) {
            if (!trait) return;
            document.getElementById('trait-detail-name').textContent = trait.name;
            const rarityEl = document.getElementById('trait-detail-rarity');
            const rarity = trait.rarity || '普通';
            rarityEl.textContent = rarity;

            const rarityConfig = CREATION_CONFIG.TRAIT_RARITIES[rarity];
            if (rarityConfig) {
                rarityEl.style.color = rarityConfig.color;
            } else {
                rarityEl.style.color = 'var(--rarity-common)';
            }

            document.getElementById('trait-detail-desc').textContent = trait.desc || trait.description || '无';
            document.getElementById('trait-detail-effects').textContent = trait.effects || '无';

            const bonusesEl = document.getElementById('trait-detail-bonuses');
            bonusesEl.innerHTML = '';
            if (trait.bonus && Object.keys(trait.bonus).length > 0) {
                Object.entries(trait.bonus).forEach(([attr, val]) => {
                    const row = document.createElement('div');
                    row.className = 'trait-detail-row';
                    row.innerHTML = `
                        <span class="trait-detail-label">${attr}</span>
                        <span class="trait-detail-value ${val > 0 ? 'bonus' : 'penalty'}">${val > 0 ? '+' : ''}${val}</span>
                    `;
                    bonusesEl.appendChild(row);
                });
            }

            const itemRow = document.createElement('div');
            itemRow.className = 'trait-detail-row';
            const itemLabel = document.createElement('span');
            itemLabel.className = 'trait-detail-label';
            itemLabel.textContent = '附带物品:';
            const itemValue = document.createElement('span');
            itemValue.className = 'trait-detail-value';

            if (trait.item && trait.item !== '无') {
                const itemMatch = trait.item.match(/【(.*?)】/);
                if (itemMatch) {
                    const parts = itemMatch[1].split('|');
                    const tempItem = {
                        name: parts[0] || '未知物品',
                        description: parts[1] || '无',
                        type: parts[2] || '杂物',
                        effect: parts[3] || '无',
                        quantity: parseInt(parts[4] || '1'),
                        value: parseInt(parts[5] || '0')
                    };
                    itemValue.textContent = `${tempItem.name} `;
                    const infoIcon = document.createElement('i');
                    infoIcon.className = 'fas fa-info-circle';
                    infoIcon.style.cursor = 'pointer';
                    infoIcon.title = '点击查看物品详情';
                    infoIcon.addEventListener('click', (e) => {
                        e.stopPropagation();
                        showItemDetail(tempItem, { isPreview: true });
                    });
                    itemValue.appendChild(infoIcon);
                } else {
                    itemValue.textContent = trait.item;
                }
            } else {
                itemValue.textContent = '无';
            }
            itemRow.appendChild(itemLabel);
            itemRow.appendChild(itemValue);
            bonusesEl.appendChild(itemRow);

            traitDetailOverlay.classList.add('visible');
        }

