            const birthLocation = creationState.birthLocation || '未知之地';
            newTableState['4'][0] = { "id": "TIME_LOCATION_ROW", "0": `0001年 春之月（1月） 1日 08:00/${birthLocation}/${birthLocation}` };

            creationState.bondedCharacters.forEach((charTemplate) => {
