                    "0": charId, "1": `${charTemplate.name}|${charTemplate.gender}`, "2": `${charTemplate.race}|${charTemplate.career}`,
                    "3": charTemplate.personality || '', "4": "一切正常", "5": charTemplate.age || '5', "6": `${maxHP_npc}|${maxHP_npc}`,
                    "7": `${maxMP_npc}|${maxMP_npc}`, "8": charTemplate.identity, "9": STARTING_LEVEL, "10": charTemplate.background,
                    "11": charTemplate.attributes || '{}', "12": charTemplate.motive || '...', "13": charTemplate.rawRelations || 'B1:初始伙伴',
                    "15": charTemplate.favorability || '50', "16": `${charTemplate.action||'无'}|${charTemplate.attire||'无'}|${birthLocation}|${charTemplate.figure||'无'}|${charTemplate.appearance||'无'}`,
