        function renderTaskList(tasks, containerId) {
            const container = document.getElementById(containerId);
            container.innerHTML = '';

            if (tasks.length === 0) {
                const messages = {
                    'unaccepted-task-list': '委托板上十分干净，没有可接取的委托。',
                    'in-progress-task-list': '你当前没有正在进行中的委托。',
                    'completed-task-list': '你没有待提交的委托。',
                    'closed-task-list': '这里空空如也，记录着你已完成或失败的过去。'
                };
                container.innerHTML = `<p style="text-align:center; opacity:0.7;">${messages[containerId]}</p>`;
                return;
            }

            tasks.forEach(task => {
                const item = document.createElement('div');
                item.className = 'task-list-item';
                const difficulty = task['5'] || '无要求';
                const difficultyColor = ADVENTURE_RANK_COLORS[difficulty] || ADVENTURE_RANK_COLORS.default;

                let deleteButtonHtml = '';
                const status = task['9'] || 'unaccepted';
                if (status === 'unaccepted' || status === 'completed') {
                    deleteButtonHtml = `<button class="item-delete-btn" data-id="${task['0']}"><i class="fas fa-trash-alt"></i></button>`;
                }

                item.innerHTML = `
                    <div class="task-info">
                        <span class="name">${task['1']}</span>
                        <span class="difficulty" style="background-color:${difficultyColor}; color: #1a1a1a;">${difficulty}</span>
                    </div>
                    ${deleteButtonHtml}
                `;

                item.querySelector('.task-info').addEventListener('click', () => showTaskDetailView(task['0']));

                const deleteBtn = item.querySelector('.item-delete-btn');
                if (deleteBtn) {
                    deleteBtn.addEventListener('click', async (e) => {
                        e.stopPropagation();
                        const taskId = e.currentTarget.dataset.id;
                        const taskName = task['1'];
                        if (await showCustomConfirm(`确定要永久删除委托 "${taskName}" 吗？此操作不可撤销。`)) {
                            delete currentState['6'][taskId];
                            await saveCurrentState();
                            renderAllTaskLists();
                        }
                    });
                }
                container.appendChild(item);
            });
        }

        function showTaskDetailView(taskId) {
            document.getElementById('task-list-view').classList.add('hidden');
            const detailView = document.getElementById('task-detail-view');
            detailView.classList.remove('hidden');

            const detailPanel = document.getElementById('task-detail-panel');
            const task = currentState['6'][taskId];
            if (!task) return;

            const difficulty = task['5'] || '无要求';
            const difficultyColor = ADVENTURE_RANK_COLORS[difficulty] || ADVENTURE_RANK_COLORS.default;
            const status = task['9'] || 'unaccepted';
            const judgementType = task['10'] || 'system_judged';

            const rankOrder = ['无要求', '黑铁', '青铜', '白银', '黄金', '白金', '秘银'];
            let playerRankIndex = rankOrder.indexOf(currentPlayerData.adventureRank);
            if (playerRankIndex === -1) {
                playerRankIndex = 0;
            }
            const requiredRankIndex = rankOrder.indexOf(difficulty);
            const canAccept = playerRankIndex >= requiredRankIndex;

            const requirementsHtml = `
                <p>冒险者等级: <strong>${difficulty}</strong> ${canAccept || status !== 'unaccepted' ? '<i class="fas fa-check-circle" style="color: #66bb6a;"></i>' : '<i class="fas fa-times-circle" style="color: #e57373;"></i>'}</p>
                <p><strong>完成条件:</strong> ${judgementType === 'ai_judged' ? (task['11'] || '由剧情决定。') : '需达成特定目标。'}</p>
                <p><strong>判定方式:</strong> <span style="font-style: italic;">${judgementType === 'ai_judged' ? '由AI判定' : '由系统自动判定'}</span></p>
            `;

            detailPanel.innerHTML = `
                <div class="task-detail-section">
                    <h5>${task['1']} <span class="task-difficulty" style="background-color:${difficultyColor}; color: #1a1a1a; float: right;">${difficulty}</span></h5>
                    <p>${task['2'] || '无'}</p>
                </div>
                <div class="detail-section">
                    <h4><i class="fas fa-tasks"></i> 任务需求</h4>
                    ${requirementsHtml}
                </div>
                <div class="detail-section">
                    <h4><i class="fas fa-gift"></i> 任务报酬</h4>
                    <p class="task-reward">${task['3'] || '无'}</p>
                </div>
                <div class="detail-section">
                    <h4><i class="fas fa-exclamation-triangle"></i> 失败惩罚</h4>
                    <p class="task-punishment">${task['4'] || '无'}</p>
                </div>
                <div class="task-detail-actions" id="task-detail-buttons"></div>
            `;

            const buttonsContainer = detailPanel.querySelector('#task-detail-buttons');
            switch(status) {
                case 'unaccepted':
                    buttonsContainer.innerHTML = `<button class="major-action-button" id="accept-task-btn" ${!canAccept ? 'disabled' : ''}><i class="fas fa-check"></i> 接受委托</button>`;
                    const acceptBtn = buttonsContainer.querySelector('#accept-task-btn');
                    if (!canAccept) acceptBtn.title = `你的冒险者等级不足 (${currentPlayerData.adventureRank})`;
                    acceptBtn.onclick = async () => {
                        if (currentState['6'][taskId]) {
                            currentState['6'][taskId]['9'] = 'in-progress';
                            await saveCurrentState();
                            showDanmaku(`已接取委托: ${currentState['6'][taskId]['1']}`, 'player');
                            showTaskDetailView(taskId);
                        }
                    };
                    break;
                case 'in-progress':
                    buttonsContainer.innerHTML = `<button class="major-action-button" id="abandon-task-btn" style="border-color: #e57373; color: #e57373;"><i class="fas fa-times"></i> 放弃委托</button>`;
                    buttonsContainer.querySelector('#abandon-task-btn').onclick = async () => {
                        const currentTask = currentState['6'][taskId];
                        if (!currentTask) return;
                        if (await showCustomConfirm(`确定要放弃委托 "${currentTask['1']}" 吗？你可能需要承担失败惩罚。`)) {
                            const penaltyCommands = currentTask['4'];
                            if (penaltyCommands) {
                                const { delta } = parseTableEditCommands(penaltyCommands);
                                const result = await applyChanges(currentState, delta);
                                currentState = result.state;
                                showDanmaku(`任务惩罚已执行！`, 'error');
                            }

                            if (currentState['6'][taskId]) {
                                currentState['6'][taskId]['9'] = 'closed';
                            }

                            await saveCurrentState();
                            syncStateFromTables();
                            showDanmaku(`已放弃委托: ${currentTask['1']}`, 'error');
                            showTaskListView();
                        }
                    };
                    break;
                case 'completed':
                    buttonsContainer.innerHTML = `<button class="major-action-button" id="submit-task-btn" style="border-color: #ffd700; color: #ffd700;"><i class="fas fa-hand-holding-usd"></i> 提交委托</button>`;
                    buttonsContainer.querySelector('#submit-task-btn').onclick = () => {
                        const currentTask = currentState['6'][taskId];
                        if (currentTask) {
                            addAction('submit_task', { id: taskId, name: currentTask['1'] });
                            tasksOverlay.classList.remove('visible');
                        }
                    };
                    break;
                case 'closed':
                    buttonsContainer.innerHTML = `<p style="opacity: 0.7; text-align: center; width: 100%;">此委托已结束。</p>`;
                    break;
            }
        }

function showTaskListView() {
    document.getElementById('task-list-view').classList.remove('hidden');
    document.getElementById('task-detail-view').classList.add('hidden');
    renderAllTaskLists();
}

function updateClearButtonVisibility() {
    const clearBtn = document.getElementById('clear-task-list-btn');
    const activeTab = document.querySelector('#task-tabs .tab-button.active');
    if (!activeTab) {
        clearBtn.style.display = 'none';
        return;
    }

    const tabName = activeTab.dataset.tab;
    if (tabName === 'in-progress') {
        clearBtn.style.display = 'none';
    } else {
        clearBtn.style.display = 'block';
        const listId = `${tabName}-task-list`;
        const list = document.getElementById(listId);
        clearBtn.disabled = !list || list.children.length === 0 || (list.children.length === 1 && list.children[0].tagName === 'P');
    }
}

async function clearCurrentTaskList() {
    const activeTab = document.querySelector('#task-tabs .tab-button.active');
    if (!activeTab) return;

    const tabName = activeTab.dataset.tab;
    const statusToClear = tabName;
    const confirmMessage = tabName === 'unaccepted' ? '确定要清空所有未接取的委托吗？' : '确定要清空所有已完成的委托记录吗？';

    if (await showCustomConfirm(confirmMessage)) {
        const allTasks = Object.values(currentState['6'] || {});
        const tasksToKeep = allTasks.filter(t => (t['9'] || 'unaccepted') !== statusToClear);

        const newTasksObject = {};
        tasksToKeep.forEach(task => {
            newTasksObject[task['0']] = task;
        });

        currentState['6'] = newTasksObject;
        await saveCurrentState();
        renderAllTaskLists();
        updateClearButtonVisibility();
    }
}

        async function openTaskItemPicker(task) {
            tasksOverlay.classList.remove('visible');

            pickerTitle.textContent = `为委托 [${task['1']}] 选择提交的物品`;
            pickerGrid.innerHTML = '';

            const requirements = (task['10'] || '').split(';').map(req => {
                const [id, count] = req.split(':');
                return { id, count: parseInt(count) };
            }).filter(r => r.id && r.count);

            const requiredItemIds = new Set(requirements.map(r => r.id));
            const submittableItems = inventoryItems.filter(item => requiredItemIds.has(item.id));

            if (submittableItems.length === 0) {
                pickerGrid.innerHTML = `<p style="grid-column: 1 / -1; text-align: center; opacity: 0.7;">你的背包中没有任务所需的物品。</p>`;
            } else {
                submittableItems.forEach(item => {
                    const slot = document.createElement('div');
                    slot.className = 'inventory-slot';
                    slot.title = `${item.name}\n类型: ${item.type}`;
                    const iconClass = itemIconMap[item.type] || itemIconMap['默认'];
                    slot.innerHTML = `<i class="fas ${iconClass} inventory-slot-icon"></i><span class="inventory-slot-name">${item.name}</span><span class="inventory-slot-quantity">${item.quantity}</span>`;

                    slot.addEventListener('click', async () => {
                        const requiredAmount = requirements.find(r => r.id === item.id).count;
                        const quantityToSubmit = await showCustomPrompt(`要提交多少个 [${item.name}]？ (需要 ${requiredAmount})`, item.quantity);
                        const numToSubmit = parseInt(quantityToSubmit);

                        if (isNaN(numToSubmit) || numToSubmit <= 0) return;
                        if (numToSubmit > item.quantity) {
                            await showCustomAlert('数量不足！');
                            return;
                        }


                        const itemInState = currentState['1'][item.id];
                        if (itemInState) {
                            const currentQuantity = parseInt(itemInState['5']);
                            if (numToSubmit >= currentQuantity) {
                                delete currentState['1'][item.id];
                            } else {
                                itemInState['5'] = (currentQuantity - numToSubmit).toString();
                            }
                        }

                        await saveCurrentState();
                        syncStateFromTables();

                        await showCustomAlert(`你提交了 ${numToSubmit} 个 [${item.name}]。`);
                        closeEquipmentPicker();

                        let allMet = true;
                        for (const req of requirements) {
                            const itemInBag = inventoryItems.find(i => i.id === req.id);
                            if (!itemInBag || itemInBag.quantity < req.count) {
                                allMet = false;
                                break;
                            }
                        }

                        if (allMet) {
                            currentState['6'][task['0']]['9'] = 'completed';
                            showDanmaku(`完成委托: ${task['1']}`, 'achievement');
                            if (task['12']) {
                                const { delta } = parseTableEditCommands(task['12']);
                                currentState = applyChanges(currentState, delta);
                            }
                            await saveCurrentState();
                            syncStateFromTables();
                        }

                        tasksOverlay.classList.add('visible');
                        showTaskDetailView(task['0']);
                    });
                    pickerGrid.appendChild(slot);
                });
            }
            pickerOverlay.classList.add('visible');
        }

