        async function renderBondedCharManager() {
            const listEl = document.getElementById('bonded-character-selection-list');
            listEl.innerHTML = '';
            const allChars = await getBondedChars();

            if (allChars.length === 0) {
                listEl.innerHTML = '<p style="text-align:center; opacity:0.7;">名册为空。</p>';
            } else {
                allChars.forEach((char) => {
                    const item = document.createElement('div');
                    item.className = 'custom-trait-item';
                    const gender = char.gender || '';
                    const genderClass = (gender === '男' || gender === '雄性') ? 'char-name-male' : ((gender === '女' || gender === '雌性') ? 'char-name-female' : '');
                    item.innerHTML = `
                        <input type="checkbox" data-id="${char.id}">
                        <span class="char-name ${genderClass}" style="flex-grow:1;">${char.name}</span>
                        <button class="edit-bonded-char-btn" data-id="${char.id}" title="编辑"><i class="fas fa-edit"></i></button>
                    `;
                    listEl.appendChild(item);
                });
            }

            const actionsContainer = document.getElementById('bonded-char-manager-actions');
            actionsContainer.innerHTML = `
                <button id="bc-create-btn" class="major-action-button"><i class="fas fa-plus"></i> 新建</button>
                <button id="bc-import-btn" class="major-action-button"><i class="fas fa-file-import"></i> 导入</button>
                <button id="bc-export-btn" class="major-action-button"><i class="fas fa-file-export"></i> 导出</button>
                <button id="bc-delete-btn" class="major-action-button"><i class="fas fa-trash"></i> 删除</button>
                <button id="bc-back-to-select-btn" class="major-action-button"><i class="fas fa-arrow-left"></i> 返回</button>
            `;

            listEl.querySelectorAll('.edit-bonded-char-btn').forEach(btn => btn.addEventListener('click', async (e) => {
                const charId = e.currentTarget.dataset.id;
                const chars = await getBondedChars();
                const index = chars.findIndex(c => c.id === charId);
                if (index > -1) {
                    openBondedCharEditor(index);
                }
            }));
            document.getElementById('bc-create-btn').addEventListener('click', () => openBondedCharEditor());
            document.getElementById('bc-import-btn').addEventListener('click', () => handleImportCustomData(CUSTOM_BONDED_CHARS_KEY, '羁绊人物'));
            document.getElementById('bc-export-btn').addEventListener('click', () => handleExportCustomData(CUSTOM_BONDED_CHARS_KEY, 'custom_bonded_chars.json'));
            document.getElementById('bc-delete-btn').addEventListener('click', async () => {
                const selectedIds = Array.from(listEl.querySelectorAll('input:checked')).map(cb => cb.dataset.id);
                if (selectedIds.length === 0) return;
                if (await showCustomConfirm(`确定要从名册中删除选中的 ${selectedIds.length} 个人物吗？`)) {
                    let chars = await getBondedChars();
                    chars = chars.filter(char => !selectedIds.includes(char.id));
                    await saveBondedChars(chars);
                    await renderBondedCharManager();
                }
            });
            document.getElementById('bc-back-to-select-btn').addEventListener('click', openBondedCharacterSelection);
        }

        function getCharacterEditorData(isNew, existingId) {
            const attributes = {};
            document.querySelectorAll('.bonded-char-attr-input').forEach(input => {
                const rawValue = input.value.trim();
                if (rawValue !== '') {
                    const value = parseInt(rawValue);
                    if (!isNaN(value)) {
                        attributes[input.dataset.attrVal] = value;
                    }
                }
            });

            const stages = [];
            document.querySelectorAll('.favor-stage').forEach(el => {
                stages.push({
                    min: parseInt(el.querySelector('.favor-min').value) || 0,
                    max: parseInt(el.querySelector('.favor-max').value) || 0,
                    attitude: el.querySelector('.favor-attitude').value,
                    description: el.querySelector('.favor-description').value
                });
            });

            const allRelations = [];
            const playerRelationText = document.getElementById('bc-editor-player-relation').value.trim();
            if (playerRelationText) { allRelations.push(`B1:${playerRelationText}`); }
            document.querySelectorAll('#bc-editor-npc-relation-list .relation-item').forEach(item => {
                allRelations.push(`${item.dataset.targetId}:${item.dataset.relationText}`);
            });

            return {
                id: isNew ? `G${crypto.randomUUID()}` : existingId,
                name: document.getElementById('bc-editor-name').value.trim(),
                gender: document.getElementById('bc-editor-gender').value,
                race: document.getElementById('bc-editor-race').value.trim(),
                career: document.getElementById('bc-editor-career').value.trim(),
                identity: document.getElementById('bc-editor-identity').value.trim(),
                age: document.getElementById('bc-editor-age').value.trim(),
                favorability: document.getElementById('bc-editor-favorability').value.trim(),
                appearance: document.getElementById('bc-editor-appearance').value.trim(),
                figure: document.getElementById('bc-editor-figure').value.trim(),
                attire: document.getElementById('bc-editor-attire').value.trim(),
                status: document.getElementById('bc-editor-status').value.trim(),
                action: document.getElementById('bc-editor-action').value.trim(),
                location: document.getElementById('bc-editor-location').value.trim(),
                personality: document.getElementById('bc-editor-personality').value.trim(),
                motive: document.getElementById('bc-editor-motive').value.trim(),
                background: document.getElementById('bc-editor-background').value.trim(),
                level: document.getElementById('bc-editor-level').value.trim() || '1',
                attributes: JSON.stringify(attributes),
                rawRelations: allRelations.join(';'),
                stages: stages
            };
        }

