        async function saveCustomClassFromEditor() {
            const name = document.getElementById('custom-class-name').value.trim();
            if (!name) { await showCustomAlert('职业名称不能为空！'); return; }

            let itemString = '无';
            const itemName = document.getElementById('custom-class-item-name').value.trim();
            if (itemName) {
                const itemDesc = document.getElementById('custom-class-item-desc').value.trim();
                const itemType = document.getElementById('custom-class-item-type').value;
