                const itemValueInput = document.getElementById('custom-class-item-value');
                let itemValue = parseInt(itemValueInput.value) || 0;
                itemValue = Math.max(0, Math.min(1000, itemValue));
                itemValueInput.value = itemValue;

                itemString = `【${itemName}|${itemDesc}|${itemType}|${itemEffect}|${itemQuantity}|${itemValue}】`;
            }

            const classData = {
                id: currentEditingCustomClassId || crypto.randomUUID(),
                name: name,
                desc: document.getElementById('custom-class-desc').value.trim(),
                item: itemString
            };

            let classes = await dbGet(CUSTOM_CLASSES_KEY) || [];
            if (currentEditingCustomClassId) {
                const index = classes.findIndex(c => c.id === currentEditingCustomClassId);
                classes[index] = classData;
            } else {
                classes.push(classData);
            }
            await dbSet(CUSTOM_CLASSES_KEY, classes);
            customClassOverlay.classList.remove('visible');
