            const updateUI = async () => {
                const storedPoints = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;
                pointsSummaryEl.textContent = tempAttributePoints;
                saveBtn.disabled = tempAttributePoints === storedPoints && JSON.stringify(tempAttributes) === JSON.stringify(currentPlayerData.detailedAttributes);

                grid.querySelectorAll('.attribute-item').forEach(item => {
                    const attr = item.querySelector('.plus').dataset.attr;
                    const currentValue = tempAttributes[attr];
