                    const costToIncrease = getPointCost(currentValue);
                    item.querySelector('.plus').disabled = tempAttributePoints < costToIncrease || currentValue >= 30;
                    item.querySelector('.plus').title = `消耗 ${costToIncrease} 点`;
                });
            };

            Object.entries(tempAttributes).forEach(([key, value]) => {
                const item = document.createElement('div');
                item.className = 'attribute-item';
                item.innerHTML = `
                    <div class="name-desc" style="flex-basis: auto;"><strong>${key}</strong></div>
                    <div class="attribute-controls">
                        <span class="value" style="border: none;">${value}</span>
