                    </div>
                `;
                grid.appendChild(item);
            });

            grid.querySelectorAll('.plus').forEach(btn => {
                btn.addEventListener('click', async () => {
                    const attr = btn.dataset.attr;
                    const currentValue = tempAttributes[attr];
                    const cost = getPointCost(currentValue);

                    if (tempAttributePoints >= cost && currentValue < 30) {
                        tempAttributePoints -= cost;
                        tempAttributes[attr]++;
