        function renderAchievementReqDetails(requirement = {}) {
            const type = document.getElementById('ca-editor-req-type').value;
            const container = document.getElementById('ca-editor-req-details');
            container.innerHTML = '';

            switch(type) {
                case 'playerData':
                    const mainCategorySelect = document.createElement('select');
                    mainCategorySelect.innerHTML = `
                        <option value="primary">核心数据</option>
                        <option value="detailedAttributes">详细属性</option>
                    `;

                    const subCategorySelect = document.createElement('select');

                    const updateSubCategory = () => {
                        const mainCat = mainCategorySelect.value;
                        subCategorySelect.innerHTML = '';
                        let options = [];
                        if (mainCat === 'primary') {
                            options = ['level', 'money', 'deathCount'];
                        } else if (mainCat === 'detailedAttributes') {
                            options = Object.keys(CREATION_CONFIG.ATTRIBUTES);
                        }
                        options.forEach(opt => {
                            const optionEl = document.createElement('option');
                            optionEl.value = opt;
                            optionEl.textContent = opt;
                            subCategorySelect.appendChild(optionEl);
                        });
                        if (requirement.key) {
                            const parts = requirement.key.split('.');
                            if (mainCat === 'detailedAttributes' && parts.length > 1) {
                                subCategorySelect.value = parts[1];
                            } else if (mainCat === 'primary') {
                                subCategorySelect.value = parts[0];
                            }
                        }
                    };

                    mainCategorySelect.addEventListener('change', updateSubCategory);

                    if (requirement.key && requirement.key.includes('.')) {
                        mainCategorySelect.value = 'detailedAttributes';
                    } else {
                        mainCategorySelect.value = 'primary';
                    }

                    updateSubCategory();

                    const opSelect = document.createElement('select');
                    opSelect.innerHTML = `<option value=">=">>=</option><option value="<="><=</option><option value="==">==</option>`;
                    if (requirement.operator) opSelect.value = requirement.operator;

                    const valueInput = document.createElement('input');
                    valueInput.type = 'number';
                    valueInput.placeholder = '目标值';
                    valueInput.value = requirement.value || '';

                    container.append(mainCategorySelect, subCategorySelect, opSelect, valueInput);
                    break;
                case 'aiResponse':
                    const keywordInput = document.createElement('input');
                    keywordInput.type = 'text';
                    keywordInput.placeholder = '关键词';
                    keywordInput.value = requirement.keyword || '';
                    container.appendChild(keywordInput);
                    break;
            }
        }

        function renderAchievementRewardDetails(reward = {}) {
            const type = document.getElementById('ca-editor-reward-type').value;
            const container = document.getElementById('ca-editor-reward-details');
            container.innerHTML = '';

            if (type === 'none') return;

            const createInput = (placeholder, value = '', inputType = 'text') => {
                const input = document.createElement('input');
                input.type = inputType;
                input.placeholder = placeholder;
                input.value = value;
                return input;
            };

            switch(type) {
                case 'item':
                    container.append(
                        createInput('奖励描述', reward.description),
                        createInput('物品ID (I开头)', reward.id), createInput('名称', reward.name), createInput('类型', reward.itemType), 
                        createInput('描述', reward.desc), createInput('效果', reward.effect), createInput('数量', reward.quantity || 1, 'number')
                    );
                    break;
                case 'character':
                    container.append(
                        createInput('奖励描述', reward.description),
                        createInput('人物ID (C开头)', reward.id), createInput('名称|性别', reward.nameGender), createInput('种族|职业', reward.raceCareer)
                    );
                    break;
                case 'pet':
                     container.append(
                        createInput('奖励描述', reward.description),
                        createInput('宠物ID (P开头)', reward.id), createInput('名称|性别', reward.nameGender), createInput('种族|类型', reward.raceType)
                    );
                    break;
                case 'task':
                    container.append(
                        createInput('奖励描述', reward.description),
                        createInput('任务ID (T开头)', reward.id), createInput('标题', reward.title), createInput('描述', reward.desc),
                        createInput('报酬', reward.reward), createInput('惩罚', reward.punishment), createInput('难度', reward.difficulty)
                    );
                    break;
                case 'world_event':
                    container.append(
                        createInput('奖励描述', reward.description),
                        createInput('时间', reward.time), createInput('地点', reward.location), createInput('事件描述', reward.desc)
                    );
                    break;
            }
        }

        async function saveCustomAchievement() {
            const name = document.getElementById('ca-editor-name').value.trim();
            if (!name) { await showCustomAlert('成就名称不能为空！'); return; }

            const reqType = document.getElementById('ca-editor-req-type').value;
            const reqDetails = document.getElementById('ca-editor-req-details').children;
            let requirement = { type: reqType };
            switch(reqType) {
                case 'playerData':
                    const mainCat = reqDetails[0].value;
                    const subCat = reqDetails[1].value;
                    requirement.key = mainCat === 'detailedAttributes' ? `detailedAttributes.${subCat}` : subCat;
                    requirement.operator = reqDetails[2].value;
                    requirement.value = reqDetails[3].value;
                    break;
                case 'aiResponse':
                    requirement.keyword = reqDetails[0].value;
                    break;
            }

            const rewardType = document.getElementById('ca-editor-reward-type').value;
            const rewardDetails = document.getElementById('ca-editor-reward-details').children;
            let reward = { type: rewardType };
            let rewardCommand = '';

            if (rewardType !== 'none') {
                try {
                    reward.description = rewardDetails[0].value;
                    switch(rewardType) {
                        case 'item':
                            reward = { ...reward, id: rewardDetails[1].value, name: rewardDetails[2].value, itemType: rewardDetails[3].value, desc: rewardDetails[4].value, effect: rewardDetails[5].value, quantity: rewardDetails[6].value };
                            rewardCommand = `insertRow(${JSON.stringify({"0":reward.id, "1":reward.name, "2":reward.itemType, "3":reward.desc, "4":reward.effect, "5":reward.quantity})})`;
                            break;
                        case 'character':
                            reward = { ...reward, id: rewardDetails[1].value, nameGender: rewardDetails[2].value, raceCareer: rewardDetails[3].value };
                            rewardCommand = `insertRow(${JSON.stringify({"0":reward.id, "1":reward.nameGender, "2":reward.raceCareer})})`;
                            break;
                        case 'pet':
                            reward = { ...reward, id: rewardDetails[1].value, nameGender: rewardDetails[2].value, raceType: rewardDetails[3].value };
                            rewardCommand = `insertRow(${JSON.stringify({"0":reward.id, "1":reward.nameGender, "2":reward.raceType})})`;
                            break;
                        case 'task':
                            reward = { ...reward, id: rewardDetails[1].value, title: rewardDetails[2].value, desc: rewardDetails[3].value, reward: rewardDetails[4].value, punishment: rewardDetails[5].value, difficulty: rewardDetails[6].value };
                            rewardCommand = `insertRow(${JSON.stringify({"0":reward.id, "1":reward.title, "2":reward.desc, "3":reward.reward, "4":reward.punishment, "5":reward.difficulty})})`;
                            break;
                        case 'world_event':
                            reward = { ...reward, time: rewardDetails[1].value, location: rewardDetails[2].value, desc: rewardDetails[3].value };
                            rewardCommand = `addWorldEvent("${reward.time}", "${reward.location}", "${reward.desc}")`;
                            break;
                    }
                } catch(e) {
                    await showCustomAlert('奖励信息格式错误，请检查。');
                    return;
                }
            }

            const achievementData = {
                id: currentEditingAchievementId || crypto.randomUUID(),
                name: name,
                description: document.getElementById('ca-editor-desc').value.trim(),
                completionText: document.getElementById('ca-editor-completion-text').value.trim(),
                quality: document.getElementById('ca-editor-quality').value,
                requirement: requirement,
                reward: rewardType !== 'none' ? { ...reward, command: rewardCommand } : null
            };

            const archive = await db.archives.get(currentArchiveName);
            const customAchievements = archive.data.state.achievements.custom || [];
            if (currentEditingAchievementId) {
                const index = customAchievements.findIndex(a => a.id === currentEditingAchievementId);
                customAchievements[index] = achievementData;
            } else {
                customAchievements.push(achievementData);
            }
            archive.data.state.achievements.custom = customAchievements;
            await db.archives.put(archive);

            customAchievementEditorOverlay.classList.remove('visible');
            await openCustomAchievementManager();
        }

        async function checkAchievements(aiResponse) {
            if (!currentArchiveName) return false;

            const archive = await db.archives.get(currentArchiveName);
            if (!archive || !archive.data.state) return false;

            if (!archive.data.state.achievements) {
                archive.data.state.achievements = { completed: [], custom: [] };
            }
            const achievementsState = archive.data.state.achievements;

            const allAchievements = [...DEFAULT_ACHIEVEMENTS, ...(achievementsState.custom || [])];
            const uncompleted = allAchievements.filter(ach => !achievementsState.completed.includes(ach.id));

            if (uncompleted.length === 0) return false;

            let changed = false;
            let commandsToExecute = [];

            const evaluateRewardCommand = (commandTemplate) => {
                if (!commandTemplate.includes('${')) return commandTemplate;
                try {
                    return commandTemplate.replace(/\${([^}]+)}/g, (match, expression) => {
                        const func = new Function('currentPlayerData', 'currentState', `return ${expression}`);
                        return func(currentPlayerData, currentState);
                    });
                } catch (e) {
                    console.error(`Error evaluating expression in achievement command: "${commandTemplate}"`, e);
                    return '';
                }
            };

            for (const ach of uncompleted) {
                let isCompleted = false;
                const req = ach.requirement;
                if (!req) continue;

                try {
                    switch(req.type) {
                        case 'playerData':
                            const getNestedProp = (obj, path) => path.split('.').reduce((o, k) => (o && o[k] !== undefined) ? o[k] : undefined, obj);
                            const playerValue = getNestedProp(currentPlayerData, req.key);
                            const targetValue = parseFloat(req.value);
                            if (playerValue !== undefined && !isNaN(playerValue) && !isNaN(targetValue)) {
                                if (req.operator === '>=') isCompleted = parseFloat(playerValue) >= targetValue;
                                else if (req.operator === '<=') isCompleted = parseFloat(playerValue) <= targetValue;
                                else isCompleted = parseFloat(playerValue) == targetValue;
                            }
                            break;
                        case 'tableCount':
                            const table = currentState[req.table] || {};
                            const count = Object.keys(table).length;
                            if (req.operator === '>=') isCompleted = count >= req.value;
                            else if (req.operator === '<=') isCompleted = count <= req.value;
                            else isCompleted = count == req.value;
                            break;
                        case 'tableFilterCount':
                            const tableToFilter = Object.values(currentState[req.table] || {});
                            const filteredCount = tableToFilter.filter(t => { try { return eval(req.filter); } catch(e) { return false; } }).length;
                            if (req.operator === '>=') isCompleted = filteredCount >= req.value;
                            else if (req.operator === '<=') isCompleted = filteredCount <= req.value;
                            else isCompleted = filteredCount == req.value;
                            break;
                        case 'aiResponse':
                            if (aiResponse && req.keyword.split('|').some(k => aiResponse.includes(k))) isCompleted = true;
                            break;
                    }
                } catch(e) { console.error(`成就 [${ach.name}] 判定失败:`, e); }

                if (isCompleted) {
                    achievementsState.completed.push(ach.id);
                    changed = true;
                    showDanmaku(`成就达成: ${ach.completionText || ach.name}`, 'achievement');
                    if (ach.reward && ach.reward.command) {
                        const evaluatedCommand = evaluateRewardCommand(ach.reward.command);
                        commandsToExecute.push(evaluatedCommand);
                    }
                    if (ach.id === 'level_25') {
                        const currentPoints = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;
                        await dbSet(`ATTRIB_POINTS_${currentArchiveName}`, currentPoints + 1);
                    }
                }
            }

            if (commandsToExecute.length > 0) {
                const { delta } = parseTableEditCommands(commandsToExecute.join(' '));
                const changesResult = await applyChanges(JSON.parse(JSON.stringify(currentState)), delta);
                currentState = changesResult.state;
                showDanmaku(`成就奖励已发放！`, 'item');
            }

            if (changed) {
                archive.data.state.achievements = achievementsState;
                await db.archives.put(archive);
                currentState.achievements = achievementsState;
                syncStateFromTables();
                if (achievementOverlay.classList.contains('visible')) {
                    await openAchievementWall();
                }
            }

            return changed;
        }

        async function checkTaskCompletion() {
            const tasksInProgress = Object.values(currentState['6'] || {}).filter(t => t['9'] === 'in-progress');
            if (tasksInProgress.length === 0) return false;

            let tasksCompletedThisTurn = [];

            for (const task of tasksInProgress) {
                if (task['10'] === 'ai_judged' || !task['11']) continue;

                let conditionsMet = false;
                try {
                    const requirements = JSON.parse(task['11']);
                    const reqArray = Array.isArray(requirements) ? requirements : [requirements];

                    const checkCondition = (req) => {
                        switch(req.type) {
                            case 'playerData':
                                const getNestedProp = (obj, path) => path.split('.').reduce((o, k) => (o && o[k] !== undefined) ? o[k] : undefined, obj);
                                const playerValue = getNestedProp(currentPlayerData, req.key);
                                const targetValue = parseFloat(req.value);
                                if (playerValue !== undefined && !isNaN(playerValue) && !isNaN(targetValue)) {
                                    if (req.operator === '>=') return parseFloat(playerValue) >= targetValue;
                                    if (req.operator === '<=') return parseFloat(playerValue) <= targetValue;
                                    return parseFloat(playerValue) == targetValue;
                                }
                                return false;
                            case 'tableCount':
                                const table = currentState[req.table] || {};
                                const count = Object.keys(table).length;
                                if (req.operator === '>=') return count >= req.value;
                                if (req.operator === '<=') return count <= req.value;
                                return count == req.value;
                            case 'tableFilterCount':
                                const tableToFilter = Object.values(currentState[req.table] || {});
                                const filteredCount = tableToFilter.filter(t => eval(req.filter)).length;
                                if (req.operator === '>=') return filteredCount >= req.value;
                                if (req.operator === '<=') return filteredCount <= req.value;
                                return filteredCount == req.value;
                            default: return false;
                        }
                    };
                    conditionsMet = reqArray.every(checkCondition);
                } catch (e) { continue; }

                if (conditionsMet) {
                    currentState['6'][task['0']]['9'] = 'completed';
                    tasksCompletedThisTurn.push(task);
                }
            }

            if (tasksCompletedThisTurn.length > 0) {
                for (const task of tasksCompletedThisTurn) {
                    showDanmaku(`任务完成: ${task['1']}`, 'achievement');
                    addMessageToLog({ content: `[系统] 任务目标已达成: ${task['1']}，可以去提交了！` }, 'system');
                }
                await saveCurrentState(); 
                syncStateFromTables();
                return true;
            }
            return false;
        }

        function setupCharacterCreatorListeners() {
            characterCreatorOverlay.querySelector('.modal-close-btn').addEventListener('click', () => characterCreatorOverlay.classList.remove('visible'));
            document.getElementById('creator-create-btn').addEventListener('click', () => openCreatorEditor());
            document.getElementById('creator-import-btn').addEventListener('click', () => handleImportCustomData(CHARACTER_TEMPLATES_KEY, '角色模板'));
            document.getElementById('creator-export-btn').addEventListener('click', () => handleExportCustomData(CHARACTER_TEMPLATES_KEY, 'character_templates.json'));
