.map-location-marker {position: absolute;transform: translate(-50%, -50%) scale(var(--map-marker-scale, 1));cursor: pointer;display: flex;flex-direction: column;align-items: center;z-index: 10;transition: transform 0.2s;}
.map-location-marker:hover {transform: translate(-50%, -50%) scale(calc(var(--map-marker-scale, 1) * 1.2));z-index: 11;}
.map-location-marker .dot {width: 10px;height: 10px;background-color: rgba(180, 142, 173, 0.8);border: 1px solid #fff;border-radius: 50%;box-shadow: 0 0 5px rgba(0,0,0,0.7);}
.map-location-marker .label {font-size: 10px;color: #fff;text-shadow: 0 0 3px #000, 0 0 5px #000;margin-top: 2px;white-space: nowrap;}
