<script>
    document.addEventListener('DOMContentLoaded', () => {
        window.crypto = window.crypto || {};
        window.crypto.randomUUID = () => {
            return Math.random().toString(36).substring(2, 7);
        };
        const playerName = "玩家";
        const GAME_VERSION = "2.2";
        async function precheckArchive(archiveName) {
            const archive = await db.archives.get(archiveName);
            if (!archive) return null;

            let hasBloatedAvatars = archive.data && archive.data.state && archive.data.state.npcAvatars && Object.keys(archive.data.state.npcAvatars).length > 0;

            if (!hasBloatedAvatars && archive.data.logs) {
                for (const log of archive.data.logs) {
                    if (log.stateSnapshot && log.stateSnapshot.includes('"npcAvatars":')) {
                        try {
                            const snapshot = JSON.parse(log.stateSnapshot);
                            if (snapshot.npcAvatars && Object.keys(snapshot.npcAvatars).length > 0) {
                                hasBloatedAvatars = true;
                                break;
                            }
                        } catch(e) { /* ignore parse errors */ }
                    }
                }
            }

            return {
                version: parseFloat(archive.data.version || "1.0"),
                hasBloatedAvatars: hasBloatedAvatars,
            };
        }
        async function migrateSaveData(archiveData) {
            let data = archiveData.data;
            let changesMade = false;
            let originalVersion = parseFloat(data.version || "1.0");

            if (originalVersion < 2.0) {
                const migrateStateObject = (stateObject) => {
                    if (!stateObject || !stateObject['0']) return false;
                    let stateChanged = false;
                    Object.values(stateObject['0']).forEach(charRow => {
                        if (charRow['9'] && typeof charRow['9'] === 'string' && charRow['9'].includes(':')) {
                            const remarks = parseRemarksString(charRow['9']);
                            delete charRow['9'];
                            charRow['9'] = parseInt(remarks.level || '1');
                            charRow['17'] = parseInt((remarks.xp || '0/0').split('/')[0]);
                            const booleans = {};
                            booleans.isBonded = remarks.isBonded === 'true';
                            booleans.isPresent = remarks.isPresent !== 'false';
                            booleans.isEssential = remarks.isEssential === 'true';
                            if (charRow['0'] === 'B1') {
                                charRow['18'] = parseInt(remarks.money || '0');
                                charRow['19'] = remarks.adventureRank || '未评定';
                                charRow['22'] = parseInt(remarks.deathCount || '0');
                                booleans.isExtreme = remarks.isExtreme === 'true';
                            }
                            charRow['20'] = serializeRemarksObject(booleans);
                            charRow['21'] = remarks.lastSeenTime || '';
                            stateChanged = true;
                        }
                    });
                    if (stateObject['7']) {
                        Object.values(stateObject['7']).forEach(petRow => {
                            if (petRow['9'] && typeof petRow['9'] === 'string' && petRow['9'].includes(':')) {
                                const remarks = parseRemarksString(petRow['9']);
                                delete petRow['9'];
                                const [currentHP, maxHP] = [remarks.currentHP, remarks.maxHP];
                                const [currentMP, maxMP] = [remarks.currentMP, remarks.maxMP];
                                petRow['6'] = `${currentHP || 0}|${maxHP || 0}`;
                                petRow['7'] = `${currentMP || 0}|${maxMP || 0}`;
                                petRow['9'] = parseInt(remarks.level || '1');
                                petRow['12'] = remarks.motive || '...';
                                petRow['17'] = parseInt((remarks.xp || '0/0').split('/')[0]);
                                petRow['20'] = `isSummoned:${remarks.isSummoned === 'true'}`;
                                petRow['23'] = remarks.skills || '';
                                stateChanged = true;
                            }
                        });
                    }
                    return stateChanged;
                };

                if (data.state && data.state.currentState) {
                    if (migrateStateObject(data.state.currentState)) changesMade = true;
                }

                if (data.logs && Array.isArray(data.logs)) {
                    data.logs.forEach(log => {
                        if (log.stateSnapshot) {
                            try {
                                const snapshotObject = JSON.parse(log.stateSnapshot);
                                const snapshotState = snapshotObject.currentState ? snapshotObject.currentState : snapshotObject;
                                if(migrateStateObject(snapshotState)) {
                                    log.stateSnapshot = JSON.stringify(snapshotObject.currentState ? { ...snapshotObject, currentState: snapshotState } : snapshotState);
                                    changesMade = true;
                                }
                            } catch(e) {
                                console.warn(`Skipping malformed snapshot in log during migration: ${log.id}`);
                            }
                        }
                    });
                }
            }

            if (originalVersion < 2.1) {
                const migratePlayerStaticData = (playerRow) => {
                    if (!playerRow || !playerRow['14']) return false;
                    try {
                        let staticData = JSON.parse(playerRow['14']);
                        let staticDataChanged = false;

                        if (staticData.birth && staticData.birth.effect) {
                            delete staticData.birth.effect;
                            staticDataChanged = true;
                        }

                        const [raceName] = (playerRow['2'] || '|').split('|');
                        const raceConfig = CREATION_CONFIG.RACES[raceName];
                        if (raceConfig && raceConfig.traits) {
                            if (!staticData.traits) staticData.traits = [];
                            raceConfig.traits.forEach(raceTrait => {
                                if (!staticData.traits.some(t => t.name === raceTrait.name)) {
                                    staticData.traits.push({
                                        name: raceTrait.name,
                                        desc: raceTrait.desc,
                                        effects: raceTrait.effects,
                                        rarity: raceTrait.rarity,
                                        isRaceTrait: true
                                    });
                                    staticDataChanged = true;
                                }
                            });
                        }

                        if (staticData.traits && staticData.traits.some(t => typeof t === 'string')) {
                             staticData.traits = staticData.traits.map(t => {
                                if(typeof t === 'string') {
                                    for (const rarity in CREATION_CONFIG.TRAITS) {
                                        const found = CREATION_CONFIG.TRAITS[rarity].find(trait => trait.name === t);
                                        if (found) return { name: found.name, desc: found.desc, effects: found.effects, rarity: rarity };
                                    }
                                    return { name: t, desc: '未知', effects: '未知', rarity: '普通' };
                                }
                                return t;
                            });
                            staticDataChanged = true;
                        }

                        if (staticDataChanged) {
                            playerRow['14'] = JSON.stringify(staticData);
                        }
                        return staticDataChanged;
                    } catch(e) { return false; }
                };

                const migrateState = (state) => {
                    if (state && state['0'] && state['0']['B1']) {
                        return migratePlayerStaticData(state['0']['B1']);
                    }
                    return false;
                };

                if (data.state && data.state.currentState) {
                    if (migrateState(data.state.currentState)) changesMade = true;
                }

                if (data.logs && Array.isArray(data.logs)) {
                    data.logs.forEach(log => {
                        if (log.stateSnapshot) {
                            try {
                                const snapshotObject = JSON.parse(log.stateSnapshot);
                                const snapshotState = snapshotObject.currentState ? snapshotObject.currentState : snapshotObject;
                                if (migrateState(snapshotState)) {
                                    log.stateSnapshot = JSON.stringify(snapshotObject.currentState ? { ...snapshotObject, currentState: snapshotState } : snapshotState);
                                    changesMade = true;
                                }
                            } catch(e) { console.warn(`Skipping malformed snapshot in log during migration: ${log.id}`); }
                        }
                    });
                }
            }

            if (originalVersion < 2.2) {
                const fixFormats = (playerRow) => {
                    if (!playerRow || !playerRow['14']) return false;
                    try {
                        let staticData = JSON.parse(playerRow['14']);
                        let dataChanged = false;

                        if (staticData.traits && Array.isArray(staticData.traits)) {
                            staticData.traits.forEach(trait => {
                                if (trait.effect && !trait.effects) {
                                    trait.effects = trait.effect;
                                    delete trait.effect;
                                    dataChanged = true;
                                }
                                if (!trait.desc) {
                                    for (const rarity in CREATION_CONFIG.TRAITS) {
                                        const found = CREATION_CONFIG.TRAITS[rarity].find(t => t.name === trait.name);
                                        if (found) {
                                            trait.desc = found.desc;
                                            dataChanged = true;
                                            break;
                                        }
                                    }
                                }
                            });
                        }

                        if (staticData.imprint && typeof staticData.imprint === 'string') {
                            const imprintName = staticData.imprint;
                            let foundImprint = null;
                            for (const rank in CREATION_CONFIG.SOUL_IMPRINTS) {
                                foundImprint = CREATION_CONFIG.SOUL_IMPRINTS[rank].find(i => i.name === imprintName);
                                if (foundImprint) break;
                            }
                            if (foundImprint) {
                                staticData.imprint = { name: foundImprint.name, effect: foundImprint.effect };
                                dataChanged = true;
                            }
                        } else if (staticData.imprint && typeof staticData.imprint === 'string' && staticData.imprintEffect) {
                            staticData.imprint = {
                                name: staticData.imprint,
                                effect: staticData.imprintEffect
                            };
                            delete staticData.imprintEffect;
                            dataChanged = true;
                        }

                        if (dataChanged) {
                            playerRow['14'] = JSON.stringify(staticData);
                        }
                        return dataChanged;
                    } catch (e) { return false; }
                };

                const migrateStateFor22 = (state) => {
                    if (state && state['0'] && state['0']['B1']) {
                        return fixFormats(state['0']['B1']);
                    }
                    return false;
                };

                if (data.state && data.state.currentState) {
                    if (migrateStateFor22(data.state.currentState)) changesMade = true;
                }

                if (data.logs && Array.isArray(data.logs)) {
                    data.logs.forEach(log => {
                        if (log.stateSnapshot) {
                            try {
                                const snapshotObject = JSON.parse(log.stateSnapshot);
                                const snapshotState = snapshotObject.currentState ? snapshotObject.currentState : snapshotObject;
                                if (migrateStateFor22(snapshotState)) {
                                    log.stateSnapshot = JSON.stringify(snapshotObject.currentState ? { ...snapshotObject, currentState: snapshotState } : snapshotState);
                                    changesMade = true;
                                }
                            } catch(e) { console.warn(`Skipping malformed snapshot in log during migration to 2.2: ${log.id}`); }
                        }
                    });
                }
            }

            if (changesMade) {
                data.version = GAME_VERSION;
            }
            return changesMade;
        }
