                const extractOptionsFromTag = (tag) => {
                    const regex = new RegExp(`<${tag}>([\\s\\S]*?)<\\/${tag}>`, 'g');
                    const optionRegex = /\[(.*?)\]/g;
                    let match;
                    while ((match = regex.exec(allBranchContent)) !== null) {
                        let option;
                        while ((option = optionRegex.exec(match[1])) !== null) {
                            allOptions.push(option[1]);
                        }
                    }
                };

