        function parseGameDate(dateString) {
            const dateRegex = /(\d{4})年\s.*?（(\d{1,2})月）\s*(\d{1,2})日\s*(\d{2}):(\d{2})/;
            const match = dateString.match(dateRegex);
            if (!match) {
                console.warn("无法解析的游戏时间格式:", dateString);
                return null;
            }

            const [, year, month, day, hour, minute] = match.map(Number);

            const totalDays = ((year - 1) * 360) + ((month - 1) * 30) + day;
            const totalMinutes = (totalDays * 24 * 60) + (hour * 60) + minute;

            return { year, month, day, hour, minute, totalMinutes };
        }

        function hexToRgb(hex) {
            const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
            return result ? {
                r: parseInt(result[1], 16),
                g: parseInt(result[2], 16),
                b: parseInt(result[3], 16)
            } : null;
        }

