                    const relationsToPlayer = allRelations.filter(r => r.to === 'B1' && r.from === char.id).map(r => r.label);
                    const relationsFromPlayer = allRelations.filter(r => r.from === 'B1' && r.to === char.id).map(r => `玩家对TA: ${r.label}`);
                    const relationsToOthers = allRelations.filter(r => r.from === char.id && r.to !== 'B1').map(r => {
