        function renderMapLocations(container, locations, isEditor, clickCallback = null, isCustomMap = false) {
            container.innerHTML = '';

            const pannable = container.closest('.map-pannable');
            const svgLayer = pannable ? pannable.querySelector('.map-svg-layer') : null;
            if (svgLayer) svgLayer.innerHTML = '';

            if (!Array.isArray(locations)) {
                console.error("渲染地图错误: 地点数据不是一个数组。");
                return;
            }

            locations.forEach((loc, index) => {
                if (!isCustomMap && loc.type === 'polygon' && loc.points && svgLayer) {
                    const polygon = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
                    const pointsStr = loc.points.map(p => `${p.x}%,${p.y}%`).join(' ');
                    polygon.setAttribute('points', pointsStr);
                    polygon.setAttribute('class', 'map-polygon');
                    svgLayer.appendChild(polygon);
                }

                if (loc.marker) {
                    const marker = document.createElement('div');
                    marker.className = 'map-location-marker';
                    marker.style.top = loc.marker.top;
                    marker.style.left = loc.marker.left;
                    marker.dataset.index = index;
                    marker.dataset.name = loc.name;
                    marker.innerHTML = `<div class="dot"></div><div class="label">${loc.name}</div>`;

                    if (!isEditor && currentPlayerData.location && currentPlayerData.location.includes(loc.name)) {
                        marker.classList.add('current-location');
                    }

                    if (clickCallback) {
                        marker.addEventListener('click', () => clickCallback(loc));
                    } else if (isEditor) {
                        marker.addEventListener('mousedown', handleMarkerMouseDown);
                        marker.addEventListener('contextmenu', handleMarkerContextMenu);
                    } else if (marker.classList.contains('current-location')) {
                        marker.addEventListener('click', () => showLocationDetail(loc));
                    } else {
                        marker.addEventListener('click', () => showLocationDetail(loc));
                    }
                    container.appendChild(marker);
                }
            });
        }

        async function updateLocationInWorldBook() {
            if (!window.parent || !window.parent.TavernHelper) return;
            try {
                const primaryLorebook = await window.parent.TavernHelper.getCurrentCharPrimaryLorebook();
                if (!primaryLorebook) return;

                const entries = await window.parent.TavernHelper.getLorebookEntries(primaryLorebook);
                let mapEntry = entries.find(e => e.comment === MAP_LORE_ENTRY_NAME);

                if (!mapEntry) {
                    await writeMapToWorldBook(currentArchiveName, currentLocationsData);
                    mapEntry = (await window.parent.TavernHelper.getLorebookEntries(primaryLorebook)).find(e => e.comment === MAP_LORE_ENTRY_NAME);
                }

                if (mapEntry) {
                    const mainLocation = currentLocationsData.find(loc => currentPlayerData.location.includes(loc.name));
                    const locationStrings = currentLocationsData.map(loc => {
                        if (loc.name === mainLocation?.name && currentPlayerData.detailedLocation && currentPlayerData.detailedLocation !== '未知') {
                            return `${loc.name}(${currentPlayerData.detailedLocation})`;
                        }
                        return loc.name;
                    });
                    const newContent = `已知地点: ${locationStrings.join(', ')}`;

                    if (mapEntry.content !== newContent) {
                        mapEntry.content = newContent;
                        await window.parent.TavernHelper.setLorebookEntries(primaryLorebook, [mapEntry]);
                    }
                }
            } catch (e) {
                console.error("更新世界书地点时出错:", e);
            }
        }

