        function calculateDistance(loc1, loc2) {
            if (!loc1?.marker || !loc2?.marker) return 0;
            const x1 = parseFloat(loc1.marker.left);
            const y1 = parseFloat(loc1.marker.top);
            const x2 = parseFloat(loc2.marker.left);
            const y2 = parseFloat(loc2.marker.top);

            const mapScale = currentPlayerData.mapScaleKm || 1000;
            const aspectRatio = document.getElementById('world-map-img').naturalHeight / document.getElementById('world-map-img').naturalWidth || 1;

            const dx = (x2 - x1) / 100;
            const dy = ((y2 - y1) / 100) * aspectRatio; 

            const distanceInKm = Math.round(Math.sqrt(dx*dx + dy*dy) * mapScale);
            return distanceInKm;
        }

        async function showLocationDetail(targetLoc) {
            const isCurrentLocation = currentPlayerData.location && currentPlayerData.location.startsWith(targetLoc.name);
            let distance = 0;

            if (!isCurrentLocation) {
                const playerLoc = Array.isArray(currentLocationsData) ? currentLocationsData.find(l => currentPlayerData.location && currentPlayerData.location.startsWith(l.name)) : null;
                if (playerLoc && playerLoc.marker && targetLoc.marker) {
                    distance = calculateDistance(playerLoc, targetLoc);
                }
            }

            document.getElementById('location-detail-name').textContent = `探索: ${targetLoc.name}`;
            document.getElementById('location-detail-distance').textContent = isCurrentLocation ? `你当前就在这里` : `距离你约 ${distance} km`;

            const contentEl = document.getElementById('location-detail-content');
            contentEl.innerHTML = '';

            const mainLocationData = currentLocationsData.find(l => l.name === targetLoc.name) || targetLoc;
            if (!mainLocationData.subLocations) {
                mainLocationData.subLocations = [];
            }

            const knownSubLocationNames = new Set(mainLocationData.subLocations.map(sl => sl.name));
            let newLocationsFound = false;

            const discoverSubLocation = (name) => {
                if (name && name !== '未知' && name !== targetLoc.name && !knownSubLocationNames.has(name)) {
                    knownSubLocationNames.add(name);
                    mainLocationData.subLocations.push({ name: name });
                    newLocationsFound = true;
                }
            };

            Object.values(characterDatabase).forEach(char => {
                if (char.location === targetLoc.name && char.detailedLocation) {
                    discoverSubLocation(char.detailedLocation);
                }
            });

            if (currentPlayerData.location === targetLoc.name && currentPlayerData.detailedLocation) {
                discoverSubLocation(currentPlayerData.detailedLocation);
            }

            if (newLocationsFound) {
                const locIndex = currentLocationsData.findIndex(l => l.name === targetLoc.name);
                if (locIndex > -1) {
                    currentLocationsData[locIndex] = mainLocationData;
                    await saveCurrentState();
                }
            }

            const createCard = (title, icon, locationString, occupants, isSubLocation = false) => {
                const card = document.createElement('div');
                card.className = 'scene-card interactive';
                if (isCurrentLocation && (currentPlayerData.detailedLocation === locationString || (currentPlayerData.detailedLocation === '未知' && locationString === targetLoc.name))) {
                    card.classList.add('player-location');
                }
                card.innerHTML = `
                    <div class="scene-card-icon"><i class="fas ${icon}"></i></div>
                    <div class="scene-card-info">
                        <div class="scene-card-title">${title}</div>
                        ${occupants ? `<div class="scene-card-occupants">人物: ${occupants}</div>` : ''}
                    </div>
                `;
                card.onclick = async () => {
                    if (await showCustomConfirm(`确定要花费时间前往 ${locationString} 吗？`)) {
                        addAction('travel', { location: locationString });
                    }
                };
                return card;
            };

            const occupantsInMain = Object.values(characterDatabase)
                .filter(c => c.detailedLocation === targetLoc.name || (c.location === targetLoc.name && (!c.detailedLocation || c.detailedLocation === '未知')))
                .map(c => c.name).join(', ');
            contentEl.appendChild(createCard(`${targetLoc.name} (主要区域)`, 'fa-map-marker-alt', targetLoc.name, occupantsInMain));

            knownSubLocationNames.forEach(subLocName => {
                const occupantsInSub = Object.values(characterDatabase)
                    .filter(c => c.detailedLocation === subLocName)
                    .map(c => c.name).join(', ');
                contentEl.appendChild(createCard(subLocName, 'fa-store', `${targetLoc.name}/${subLocName}`, occupantsInSub, true));
            });

            const addSubLocationBtn = document.createElement('button');
            addSubLocationBtn.className = 'major-action-button';
            addSubLocationBtn.style.marginTop = '15px';
            addSubLocationBtn.innerHTML = '<i class="fas fa-plus-circle"></i> 手动添加子地点';
            addSubLocationBtn.onclick = async () => {
                const subLocationName = await showCustomPrompt(`在 [${targetLoc.name}] 内添加新的子地点:`);
                if (subLocationName && subLocationName.trim() !== "") {
                    const locIndex = currentLocationsData.findIndex(l => l.name === targetLoc.name);
                    if (locIndex > -1) {
                        if (!currentLocationsData[locIndex].subLocations) {
                            currentLocationsData[locIndex].subLocations = [];
                        }
                        if (!currentLocationsData[locIndex].subLocations.some(sl => sl.name === subLocationName.trim())) {
                            currentLocationsData[locIndex].subLocations.push({ name: subLocationName.trim() });
                            await saveCurrentState();
                            await showLocationDetail(targetLoc);
                        } else {
                            await showCustomAlert('该子地点已存在。');
                        }
                    }
                }
            };
            contentEl.appendChild(addSubLocationBtn);

            locationDetailOverlay.classList.add('visible');
        }

