        function setupMapInteraction(viewport, pannable) {
            let scale = 1, panX = 0, panY = 0, minScale = 1;
            let isPanning = false, isPinching = false;
            let startPos = { x: 0, y: 0 };
            let initialPinchDistance = 0;
            let tipTimeout;
            let hasShownTouchTip = false;

            const tipElement = viewport.querySelector('#map-zoom-tip');

            const calculateMinScale = () => {
                const viewportRect = viewport.getBoundingClientRect();
                const pannableRect = pannable.getBoundingClientRect();
                if (pannableRect.width === 0 || pannableRect.height === 0) return 1;
                const scaleX = viewportRect.width / pannableRect.width;
                const scaleY = viewportRect.height / pannableRect.height;
                minScale = Math.min(scaleX, scaleY);
            };

            const showTip = () => {
                if (!tipElement) return;
                clearTimeout(tipTimeout);
                tipElement.style.opacity = '1';
                tipTimeout = setTimeout(() => {
                    tipElement.style.opacity = '0';
                }, 2500);
            };

            viewport.addEventListener('mouseenter', showTip);

            viewport.addEventListener('touchstart', () => {
                if (!hasShownTouchTip) {
                    showTip();
                    hasShownTouchTip = true;
                }
            }, { once: true });

            const updateTransform = () => {
                pannable.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
                const markerScale = 1 / scale;

                pannable.querySelectorAll('.map-location-marker, .map-character-marker').forEach(marker => {
                    marker.style.setProperty('--map-marker-scale', markerScale);
                });

                pannable.dataset.panX = panX;
                pannable.dataset.panY = panY;
                pannable.dataset.scale = scale;
            };

            const getEventCoords = (e) => e.touches ? e.touches[0] : e;
            const getPinchDistance = (e) => {
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                return Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            };

            const onPanStart = (e) => {
                isPanning = true;
                const coords = getEventCoords(e);
                startPos = { x: coords.clientX - panX, y: coords.clientY - panY };
            };

            const onPanMove = (e) => {
                if (!isPanning || isPinching) return;
                e.preventDefault();
                const coords = getEventCoords(e);
                panX = coords.clientX - startPos.x;
                panY = coords.clientY - startPos.y;
                updateTransform();
            };

            const onPanEnd = () => {
                isPanning = false;
            };

            const onWheel = (e) => {
                e.preventDefault();
                const rect = viewport.getBoundingClientRect();
                const mouseX = e.clientX - rect.left;
                const mouseY = e.clientY - rect.top;

                const scaleAmount = -e.deltaY * 0.001;
                const newScale = Math.max(minScale, scale + scaleAmount);

                const worldX = (mouseX - panX) / scale;
                const worldY = (mouseY - panY) / scale;

                panX = mouseX - worldX * newScale;
                panY = mouseY - worldY * newScale;
                scale = newScale;

                updateTransform();
            };

            const onTouchStart = (e) => {
                if (e.touches.length === 2) {
                    isPinching = true;
                    isPanning = false;
                    initialPinchDistance = getPinchDistance(e);
                } else if (e.touches.length === 1) {
                    onPanStart(e);
                }
            };

            const onTouchMove = (e) => {
                if (isPinching && e.touches.length === 2) {
                    e.preventDefault();
                    const newPinchDistance = getPinchDistance(e);
                    const scaleMultiplier = newPinchDistance / initialPinchDistance;

                    const rect = viewport.getBoundingClientRect();
                    const t1 = e.touches[0], t2 = e.touches[1];
                    const pinchCenterX = ((t1.clientX + t2.clientX) / 2) - rect.left;
                    const pinchCenterY = ((t1.clientY + t2.clientY) / 2) - rect.top;

                    const newScale = Math.max(minScale, scale * scaleMultiplier);

                    const worldX = (pinchCenterX - panX) / scale;
                    const worldY = (pinchCenterY - panY) / scale;

                    panX = pinchCenterX - worldX * newScale;
                    panY = pinchCenterY - worldY * newScale;
                    scale = newScale;

                    initialPinchDistance = newPinchDistance;
                    updateTransform();
                } else if (isPanning) {
                    onPanMove(e);
                }
            };

            const onTouchEnd = (e) => {
                if (isPinching && e.touches.length < 2) {
                    isPinching = false;
                }
                if (isPanning && e.touches.length === 0) {
                    onPanEnd();
                }
            };

            viewport.onmousedown = null;
            viewport.onmousemove = null;
            viewport.onmouseup = null;
            viewport.onmouseleave = null;
            viewport.onwheel = null;
            viewport.ontouchstart = null;
            viewport.ontouchmove = null;
            viewport.ontouchend = null;

            viewport.onmousedown = onPanStart;
            viewport.onmousemove = onPanMove;
            viewport.onmouseup = onPanEnd;
            viewport.onmouseleave = onPanEnd;
            viewport.onwheel = onWheel;
            viewport.ontouchstart = onTouchStart;
            viewport.ontouchmove = onTouchMove;
            viewport.ontouchend = onTouchEnd;

            calculateMinScale();
            scale = minScale;
            panX = 0;
            panY = 0;
            updateTransform();

            const viewportRect = viewport.getBoundingClientRect();
            const pannableRect = pannable.getBoundingClientRect();

            panX = (viewportRect.width - (pannableRect.width / scale)) / 2;
            panY = (viewportRect.height - (pannableRect.height / scale)) / 2;

            updateTransform();
        }

        function sanitizeCustomTraitForGameState(trait) {
            const cleanTrait = {
                name: trait.name,
                desc: trait.desc,
                effects: trait.effects,
                bonus: trait.bonus,
                rarity: trait.rarity
            };
            return cleanTrait;
        }

        async function handleStartGame() {
            const archiveName = await showCustomPrompt("为你的传奇人生命名:", "异界宿命");
            if (!archiveName || archiveName.trim() === "") return;

            const existing = await db.archives.get(archiveName.trim());
            if (existing) {
                await showCustomAlert("该名称的存档已存在！");
                return;
            }

            const STARTING_LEVEL = 5;
            const finalAttributes = { ...creationState.attributes };

            let birthName, birthDesc, birthBonus;
            if (creationState.selectedBirth === '自定义') {
                const customBirth = creationState.customBirth || {};
                birthName = customBirth.name || '未知';
                birthDesc = customBirth.description || '';
                birthBonus = customBirth.bonus || {};
            } else {
                const birthData = CREATION_CONFIG.BIRTHS[creationState.selectedBirth];
                birthName = creationState.selectedBirth;
                birthDesc = birthData.desc;
                birthBonus = birthData.bonus;
            }
            if(birthBonus) Object.entries(birthBonus).forEach(([key, val]) => {
                const minValue = (key === '信仰' || key === '深渊亲和') ? 0 : 1;
                finalAttributes[key] = Math.max(minValue, (finalAttributes[key] || 0) + val);
            });

            let raceName, raceDesc, raceTraits, raceDataForStatic;
            if (creationState.selectedRace === '自定义') {
                const customRace = creationState.customRace || {};
                raceName = customRace.name || customRace.tag || '未知';
                raceDesc = customRace.description || '';
                raceTraits = customRace.traits || [];
                raceDataForStatic = { name: raceName, effect: (raceTraits[0] || {}).effects || '无特殊效果' };
            } else {
                const raceData = CREATION_CONFIG.RACES[creationState.selectedRace];
                raceName = creationState.selectedRace;
                raceDesc = raceData.desc;
                raceTraits = raceData.traits || [];
                raceDataForStatic = { name: raceName, effect: (raceTraits[0] || {}).effects || '无特殊效果' };
            }

            const allTraits = [...raceTraits, ...creationState.selectedTraits];
            const itemStrings = [];

            let finalCareerName = creationState.selectedCareer;
            let finalCareerItem = '';
            if (creationState.selectedCareer === '自定义' && creationState.customCareer) {
                finalCareerName = creationState.customCareer.name;
                finalCareerItem = creationState.customCareer.item || '';
            } else {
                const careerData = CREATION_CONFIG.CLASSES[creationState.selectedCareer];
                if (careerData) finalCareerItem = careerData.item || '';
            }
            if (finalCareerItem && finalCareerItem !== '无') itemStrings.push(finalCareerItem);

            const traitsForStatic = [];
            allTraits.forEach(trait => {
                const cleanTrait = sanitizeCustomTraitForGameState(trait);

                cleanTrait.isRaceTrait = raceTraits.some(rt => rt.name === trait.name);
                traitsForStatic.push({ name: cleanTrait.name, desc: cleanTrait.desc, effects: cleanTrait.effects, rarity: cleanTrait.rarity, isRaceTrait: cleanTrait.isRaceTrait });

                if (trait.bonus) {
                    Object.entries(trait.bonus).forEach(([key, val]) => {
                        const minValue = (key === '信仰' || key === '深渊亲和') ? 0 : 1;
                        finalAttributes[key] = Math.max(minValue, (finalAttributes[key] || 0) + val);
                    });
                }
                if (trait.item && trait.item !== '无') itemStrings.push(trait.item);
            });

            const startingInventory = [];
            itemStrings.forEach(itemString => {
                if (!itemString || itemString === '无') return;
                const itemMatch = itemString.match(/【(.*?)】/);
