                    const parts = itemMatch[1].split('|');
                    startingInventory.push({
                        name: parts[0] || '未知物品', description: parts[1] || '无', type: parts[2] || '杂物',
                        effect: parts[3] || '无', quantity: parseInt(parts[4] || '1'), value: parseInt(parts[5] || '0'),
                    });
