            const wisModifier = Math.floor(((finalAttributes['精神'] || 10) - 10) / 2);
            const maxHP = 10 + (STARTING_LEVEL * (5 + conModifier));
            const maxMP = 10 + (STARTING_LEVEL * (3 + intModifier + wisModifier));

