        <strong>背景:</strong> ${birthName}
        <strong>灵魂印记:</strong> ${creationState.selectedImprint.name}
        <strong>天赋:</strong> ${traitsForStatic.map(t => `[${t.rarity}]${t.name}`).join(', ') || '无'}
                </details>
                <details>
                    <summary><strong>你的初始能力</strong></summary>
