                imprint: { name: creationState.selectedImprint.name, effect: creationState.selectedImprint.effect }
            });

            const playerRow = {
                "0": "B1", "1": `${playerName}|${creationState.selectedGender || '未知'}`, "2": `${raceName}|${finalCareerName}`, "4": "一切正常",
                "5": `${creationState.initialAge || 18}`, "6": `${maxHP}|${maxHP}`, "7": `${maxMP}|${maxMP}`, "8": birthName,
                "9": STARTING_LEVEL, "10": `一位${birthName}，拥有${raceName}的血脉。`, "11": JSON.stringify(finalAttributes),
                "14": playerStaticData, "17": 0, "18": 100, "19": "未评定", "20": playerBooleans, "22": 0
            };
            newTableState['0']['B1'] = playerRow;

            startingInventory.forEach((item, index) => {
                const itemId = `I_START_${index+1}`;
                newTableState['1'][itemId] = { "0": itemId, "1": item.name, "2": item.type, "3": item.description, "4": item.effect, "5": item.quantity.toString(), "6": "", "7": item.value.toString() };
