                const intModifier_npc = Math.floor(((attributes['智力'] || 10) - 10) / 2);
                const wisModifier_npc = Math.floor(((attributes['精神'] || 10) - 10) / 2);
                const maxHP_npc = 10 + (STARTING_LEVEL * (5 + conModifier_npc));
