        function showSkillDetail(skill) {
            const nameEl = document.getElementById('skill-detail-name');
            const contentEl = document.getElementById('skill-detail-content');

            showOverlaySafely(skillDetailOverlay, () => {
                const [level, xp] = (skill['4'] || '1|0').split('|').map(Number);
                const tier = parseInt(skill['3']);
                const maxLevel = getSkillMaxLevel(tier);
                const xpToNext = calculateSkillXPForLevel(level, tier);
                const createRow = (label, value) => { if (value === null || value === undefined || value === '') return ''; return `<div class="skill-detail-row"><span class="skill-detail-label">${label}:</span><span class="skill-detail-value">${value}</span></div>`; };
                let xpBarHtml = '';
                if (level < maxLevel) {
                    const progressPercentage = xpToNext > 0 ? (xp / xpToNext) * 100 : 100;
                    xpBarHtml = `<div class="skill-detail-row"><span class="skill-detail-label">当前熟练度:</span><div class="xp-bar"><div class="xp-bar-fill" style="width: ${progressPercentage}%"></div><div class="xp-bar-text">${xp} / ${xpToNext}</div></div></div>`;
                }
                let successRateHtml = '';
                if (skill['10']) {
                    const baseChance = parseInt(skill['10']);
                    const senseBonus = Math.floor(((currentPlayerData.detailedAttributes['感应'] || 10) - 10) / 2);
                    const luckBonus = Math.floor(((currentPlayerData.detailedAttributes['幸运'] || 10) - 10) / 4);
                    const finalChance = Math.max(0, Math.min(100, baseChance + senseBonus + luckBonus));
                    successRateHtml = createRow('基础成功率', `${finalChance}%`);
                }
                let effectsHtml = '';
                if (skill['9']) {
                    try {
                        const effects = JSON.parse(skill['9']);
                        effectsHtml = effects.map(effect => {
                            let effectBlock = `<div class="detail-section"><h4>效果: ${effect['0']}</h4>`;
                            if (effect['0'] === '伤害' || effect['0'] === '治疗') {
                                const growth = SKILL_SYSTEM_CONFIG.EFFECT_GROWTH_PER_LEVEL(effect, level, tier);
                                const finalDice = `${parseInt(effect['1'].split('d')[0]) + growth.diceCount}d${growth.diceType.split('d')[1]}`;
                                effectBlock += createRow('基础数值', `${finalDice} + ${growth.flat}`);
                                if (effect['2'] && effect['3']) { try { const attributes = JSON.parse(effect['2']); const scales = JSON.parse(effect['3']); if (Array.isArray(attributes) && Array.isArray(scales) && attributes.length === scales.length) { const bonusStrings = attributes.map((attr, index) => `${scales[index] * 100}% ${attr}`); effectBlock += createRow('属性倍率', bonusStrings.join(' + ')); } } catch (e) {} }
                            } else if (effect['0'] === '增益' || effect['0'] === '削弱') {
                                effectBlock += createRow('状态名称', effect['1']);
                                if(effect['3'] !== undefined) effectBlock += createRow('基础成功率', `${effect['3']}%`);
                                if(effect['2'] !== undefined) effectBlock += createRow('基础持续时间', `${effect['2']} 回合`);
                                if (effect['4']) {
                                    try {
                                        let effectDetails;
                                        if (typeof effect['4'] === 'string') {
                                            effectDetails = JSON.parse(effect['4']);
                                        } else if (typeof effect['4'] === 'object') {
                                            effectDetails = effect['4'];
                                        }
                                        if (Array.isArray(effectDetails)) {
                                            let detailsContent = '<ul class="effect-detail-list">';
                                            effectDetails.forEach(detail => {
                                                detailsContent += `<li>${String(detail)}</li>`;
                                            });
                                            detailsContent += '</ul>';
                                            effectBlock += createRow('效果详情', detailsContent);
                                        }
                                    } catch (e) {
                                        console.error("Error parsing skill effect details:", e);
                                    }
                                }
                            }
                            effectBlock += '</div>'; return effectBlock;
                        }).join('');
                    } catch (e) { effectsHtml = '<p>效果数据格式错误。</p>'; }
                }
                nameEl.textContent = skill['1'];
                contentEl.innerHTML = `${createRow('名称', skill['1'])}${createRow('类型', skill['2'])}${createRow('阶位', `${tier} 阶`)}${createRow('当前等级', `${level}`)}${xpBarHtml}${createRow('标签', skill['5'])}${createRow('作用目标', skill['6'])}${createRow('基础消耗', calculateSkillCost(skill, level))}${successRateHtml}${createRow('描述', skill['8'])}${effectsHtml}`;
            });
        }

        async function handleAvatarUpload(event) {
            const file = event.target.files[0];
            if (!file) {
                event.target.value = '';
                return;
            }

            const reader = new FileReader();
            reader.onload = async (e) => {
                try {
                    const base64String = e.target.result;
                    if (creationScreen.classList.contains('hidden')) {
                        await dbSet(`${CUSTOM_AVATAR_KEY}_${currentArchiveName}`, base64String);
                        await updateAvatar(currentPlayerData);
                        characterDetailOverlay.classList.remove('visible');
                    } else {

                        creationState.customAvatar = base64String;
                        showCustomAlert("自定义形象已设置！");
                    }
                } catch (err) {
                    console.error("Avatar handling failed:", err);
                } finally {
                    event.target.value = '';
                }
            };
            reader.readAsDataURL(file);
        }

