        function validateCustomBirthStructure(birth) {
            if (!birth.name) return '出身名称缺失。';
            if (!birth.description) return '出身描述缺失。';
            if (typeof birth.bonus !== 'object' || birth.bonus === null) return '属性修正(bonus)数据缺失或格式错误。';
            return null;
        }

        function validateCustomRaceStructure(race) {
            if (!race.name && !race.tag) return '种族名称缺失。';
            if (!race.description) return '种族描述缺失。';
            if (typeof race.base_attributes !== 'object' || race.base_attributes === null) return '基础属性(base_attributes)数据缺失或格式错误。';
            if (!Array.isArray(race.traits)) return '种族天赋(traits)数据格式错误，应为数组。';
            if (race.traits.length > 1) return '自定义种族最多只能拥有一个天赋，请在编辑器中修正。';
            return null;
        }

        function validateCustomTraitStructure(trait) {
            if (!trait.name) return '天赋名称缺失。';
            if (!trait.rarity || !CREATION_CONFIG.TRAIT_RARITIES[trait.rarity]) return `天赋品质(rarity)“${trait.rarity}”无效。`;
            if (typeof trait.bonus !== 'object' || trait.bonus === null) return '属性修正(bonus)数据缺失或格式错误。';
            return null;
        }

        function validateBondedCharStructure(char) {
            if (!char.name) return '羁绊人物姓名缺失。';
            if (!char.gender) return '性别信息缺失。';
            if (!char.race) return '种族信息缺失。';
            if (!char.career) return '职业信息缺失。';
            if (typeof char.attributes !== 'string') return '属性(attributes)数据缺失或不是字符串格式。';
            try {
                const attrs = JSON.parse(char.attributes);
                if (typeof attrs !== 'object' || attrs === null) return '属性(attributes)JSON解析后不是一个对象。';
            } catch (e) {
                return '属性(attributes)无法被解析为有效的JSON。';
            }
            return null;
        }

