                            <button data-id="${item.id}" data-action="delete" title="删除"><i class="fas fa-trash"></i></button>
                        </div>
                    `;
                    div.querySelector('.item-name').addEventListener('click', async () => {
                        const validationError = validator(item);
                        if (validationError) {
                            await showCustomAlert(`无法选择，数据格式不正确：\n\n${validationError}\n\n请点击编辑按钮进行修正。`);
                            return;
                        }

                        if (type === 'class') {
                            creationState.selectedCareer = '自定义';
                            creationState.customCareer = item;
                        } else {
                            const currentRemaining = calculateRemainingPoints();
                            const costKey = type === 'birth' ? 'BIRTHS' : 'RACES';
                            const oldCost = creationState[type === 'birth' ? 'selectedBirth' : 'selectedRace'] ? (CREATION_CONFIG[costKey]?.['自定义']?.cost || 0) : 0;
                            const newCost = CREATION_CONFIG[costKey]?.['自定义']?.cost || 0;

                            if (currentRemaining + oldCost < newCost) {
                                await showCustomAlert('宿命点数不足，无法选择此项！');
                                return;
                            }
                            creationState[type === 'birth' ? 'selectedBirth' : 'selectedRace'] = '自定义';
                            creationState[type === 'birth' ? 'customBirth' : 'customRace'] = item;
                        }

                        if (type === 'race') {
                            const newBase = item.base_attributes || {};
                            Object.keys(CREATION_CONFIG.ATTRIBUTES).forEach(key => {
                                const isSpecial = key === '信仰' || key === '深渊亲和';
                                creationState.attributes[key] = newBase[key] !== undefined ? newBase[key] : (isSpecial ? 0 : 8);
                            });
                        }

                        overlay.classList.remove('visible');
                        renderCreationStep();
                    });
                    listEl.appendChild(div);
                });
            }

            listEl.querySelectorAll('button').forEach(btn => {
                btn.addEventListener('click', async (e) => {
                    e.stopPropagation();
