        async function openAttributeAllocator() {
            if (!currentArchiveName) {
                showCustomAlert('请先进入一个存档！');
                return;
            }
            const overlay = document.getElementById('attribute-allocator-overlay');
            const pointsSummaryEl = document.getElementById('attribute-points-summary').querySelector('.cost');
            const grid = document.getElementById('attribute-allocator-grid');
            const saveBtn = document.getElementById('save-attribute-points-btn');

            const fabAttributeBtn = document.querySelector('.fab-item[data-action="attributes"]');
            const dot = fabAttributeBtn?.querySelector('.red-dot');
            if(dot) dot.remove();

            tempAttributePoints = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;
            tempAttributes = { ...JSON.parse(JSON.stringify(currentPlayerData.detailedAttributes || {})) };

            pointsSummaryEl.textContent = tempAttributePoints;
            grid.innerHTML = '';
            saveBtn.disabled = true;

            const updateUI = async () => {
                const storedPoints = await dbGet(`ATTRIB_POINTS_${currentArchiveName}`) || 0;
                pointsSummaryEl.textContent = tempAttributePoints;
                saveBtn.disabled = tempAttributePoints === storedPoints && JSON.stringify(tempAttributes) === JSON.stringify(currentPlayerData.detailedAttributes);

                grid.querySelectorAll('.attribute-item').forEach(item => {
                    const attr = item.querySelector('.plus').dataset.attr;
                    const currentValue = tempAttributes[attr];
                    item.querySelector('.value').textContent = currentValue;
                    const costToIncrease = getPointCost(currentValue);
                    item.querySelector('.plus').disabled = tempAttributePoints < costToIncrease || currentValue >= 30;
                    item.querySelector('.plus').title = `消耗 ${costToIncrease} 点`;
                });
            };

            Object.entries(tempAttributes).forEach(([key, value]) => {
                const item = document.createElement('div');
                item.className = 'attribute-item';
                item.innerHTML = `
                    <div class="name-desc" style="flex-basis: auto;"><strong>${key}</strong></div>
                    <div class="attribute-controls">
                        <span class="value" style="border: none;">${value}</span>
                        <button class="attr-btn plus" data-attr="${key}">+</button>
                    </div>
                `;
                grid.appendChild(item);
            });

            grid.querySelectorAll('.plus').forEach(btn => {
                btn.addEventListener('click', async () => {
                    const attr = btn.dataset.attr;
                    const currentValue = tempAttributes[attr];
                    const cost = getPointCost(currentValue);

                    if (tempAttributePoints >= cost && currentValue < 30) {
                        tempAttributePoints -= cost;
                        tempAttributes[attr]++;
                        await updateUI();
                    }
                });
            });

            await updateUI();
            overlay.classList.add('visible');
        }

