        async function handlePlayerDeath() {
            await showCustomAlert("你的旅程在此终结...但命运的丝线尚未断裂。");

            const archive = await db.archives.get(currentArchiveName);
            if (!archive) return;

            const firstLog = archive.data.logs.find(log => log.content.includes('<h4>命运初动 星辰回响</h4>'));
            if (!firstLog || !firstLog.stateSnapshot) {
                await showCustomAlert("错误：找不到初始存档快照，无法回溯。请检查存档是否损坏。");
                return;
            }

            const initialTableState = JSON.parse(firstLog.stateSnapshot);

            const initialPlayerRow = initialTableState['0']['B1'];
            const initialRemarks = parseRemarksString(initialPlayerRow['9']);
            initialRemarks.deathCount = (currentPlayerData.deathCount || 0) + 1;
            initialPlayerRow['9'] = serializeRemarksObject(initialRemarks);

            const warehouseItems = currentPlayerData.warehouse || [];
            warehouseItems.forEach(item => {
                const tableIndex = getTableIndexFromId(item.id);
                if (tableIndex !== null && currentState[tableIndex] && currentState[tableIndex][item.id]) {
                    initialTableState[tableIndex][item.id] = currentState[tableIndex][item.id];
                }
            });

            archive.data.state.currentState = initialTableState;

            firstLog.stateSnapshot = JSON.stringify(initialTableState);
            archive.data.logs = [firstLog];
            archive.data.state.bondedCharacters = {};
            archive.data.state.rpgMaps = {};

            await db.archives.put(archive);
            await selectAndLoadArchive(currentArchiveName);
        }

